INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('75e685c6-e246-425d-8a2b-e1bf69d6af19'::uuid, 'card_description', 'A 3rd-century Roman temple to the mystery god Mithras, discovered during construction in 1954. The entire building was relocated stone by stone to allow modern development above it.', 'Built partly underground, the London Mithraeum came to light in 1954. Buried with care inside lay finely detailed white marble likenesses of Minerva, Mercury, Mithras and Serapis.', 'teaser-card-s009:75e685c6-e246-425d-8a2b-e1bf69d6af19:card_description', 'teaser-card-s009 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '862c4c1c3420821b03953e2b14ce4f6fdbad277260adfd1fd1f872ff8b0b45f4|21450afffdeb0e3cbe30b8d4d65994b9f796f60b6a43a37a83b3dceac10bce57|21450afffdeb0e3cbe30b8d4d65994b9f796f60b6a43a37a83b3dceac10bce57', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Built partly underground, the London Mithraeum came to light in 1954. Buried with care inside lay finely detailed white marble likenesses of Minerva, Mercury, Mithras and Serapis."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Mithraeum was built partly underground [S6]; it came to light (was discovered) in 1954 [S1]; the likenesses were found inside the temple [S4]; the likenesses had been carefully buried [S4]; the likenesses are finely detailed [S4]; the likenesses are of white marble [S4]; the likenesses represent Minerva, Mercury, Mithras and Serapis [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The London Mithraeum is a Roman Mithraeum (temple of Mithras) in London, England (central claim: a temple, in London). [SUPPORTED: https://en.wikipedia.org/wiki/London_Mithraeum]; The London Mithraeum was built partly underground. [SUPPORTED: https://en.wikipedia.org/wiki/London_Mithraeum]; The site came to light in 1954. [SUPPORTED: https://en.wikipedia.org/wiki/London_Mithraeum]; The likenesses lay inside the temple. [SUPPORTED: https://en.wikipedia.org/wiki/London_Mithraeum]; The likenesses were buried with care. [SUPPORTED: https://en.wikipedia.org/wiki/London_Mithraeum]; The likenesses are finely detailed. [SUPPORTED: https://en.wikipedia.org/wiki/London_Mithraeum]; The likenesses are made of white marble. [SUPPORTED: https://en.wikipedia.org/wiki/London_Mithraeum]; Among the likenesses are Minerva and Mercury. [SUPPORTED: https://en.wikipedia.org/wiki/London_Mithraeum]; Among the likenesses are Mithras and Serapis. [SUPPORTED: https://en.wikipedia.org/wiki/London_Mithraeum]"}]'::jsonb),
    ('75fdea5d-2f5f-4191-81d4-096ddd468da5'::uuid, 'card_description', 'A Bronze Age funerary hypogeum from 1700-1400 BC, emptied centuries ago and reused as cattle shelter. A rare vertical stone doorway still blocks the entrance.', 'A stepped corridor leads into the Hypogeum of Torre del Ram, a Bronze Age tomb whose chamber is ringed by a stone bench, its walls engraved with three sailing ships and undetermined figures.', 'teaser-card-s009:75fdea5d-2f5f-4191-81d4-096ddd468da5:card_description', 'teaser-card-s009 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', 'e97873f2193411a596507e911685e9a013616470fe9a4de7e206757e6e21cb4b|4bd0589a18ca21307fe8305b511b521e94eab9bf6860b198c882f06503a0312f|4bd0589a18ca21307fe8305b511b521e94eab9bf6860b198c882f06503a0312f', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "A stepped corridor leads into the Hypogeum of Torre del Ram, a Bronze Age tomb whose chamber is ringed by a stone bench, its walls engraved with three sailing ships and undetermined figures."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "a stepped corridor leads to the chamber of the hypogeum [S4]; the site is a tomb [S2]; the tomb dates to the Bronze Age [S2]; the chamber is ringed by a stone bench [S4]; the chamber walls are engraved [S7]; the engravings show three sailing ships [S7]; the engravings include other figures that are undetermined [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Hypogeum of Torre del Ram is a tomb (central claim: a funerary hypogeum, collective tomb). [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Torre_del_Ram]; The tomb is of the Bronze Age. [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Torre_del_Ram]; The hypogeum is in Ciutadella de Menorca, Spain. [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Torre_del_Ram]; A stepped corridor leads into the tomb. [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Torre_del_Ram]; The tomb has a chamber, reached by the corridor. [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Torre_del_Ram]; The chamber is ringed by a stone bench. [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Torre_del_Ram]; The chamber walls are engraved. [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Torre_del_Ram]; The engravings show three sailing ships. [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Torre_del_Ram]; The engravings include other figures whose nature is undetermined. [SUPPORTED: https://en.wikipedia.org/wiki/Hypogeum_of_Torre_del_Ram]"}]'::jsonb),
    ('765bec0e-b003-467c-aee3-d142f184c66d'::uuid, 'card_description', '1st-century AD Roman road linking the Iceni capital at Venta Icenorum to the legionary base at Camulodunum, later extended toward Londinium — a lifeline connecting the conquered east of Britannia.', 'Pye Road, a Roman road, ran from Venta Icenorum, capital of the Iceni, to Camulodunum, the original Roman provincial capital and legionary base. The A140 partly follows its route.', 'teaser-card-s009:765bec0e-b003-467c-aee3-d142f184c66d:card_description', 'teaser-card-s009 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'ad027950d280288d49aa5c63e98311dbe9e1f9d202599bebda4464c00a8ae718|b4c3a28884435ec0cf92c95897a32ae9c646989ecb08a21c02c68c2e18b66176|b4c3a28884435ec0cf92c95897a32ae9c646989ecb08a21c02c68c2e18b66176', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Pye Road, a Roman road, ran from Venta Icenorum, capital of the Iceni, to Camulodunum, the original Roman provincial capital and legionary base. The A140 partly follows its route."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Pye Road is a Roman road [S1]; it ran from Venta Icenorum to Camulodunum [S1, S3]; Venta Icenorum was the capital of the Iceni [S1]; Camulodunum was the original Roman provincial capital [S1]; Camulodunum was a legionary base [S1]; the A140 partly shares/follows the route of the road [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Pye Road is a Roman road (central claim: a road, in England, Norwich to Colchester). [SUPPORTED: https://en.wikipedia.org/wiki/Pye_Road]; The road ran from Venta Icenorum. [SUPPORTED: https://en.wikipedia.org/wiki/Pye_Road]; Venta Icenorum was the capital of the Iceni. [SUPPORTED: https://en.wikipedia.org/wiki/Pye_Road]; The road ran to Camulodunum. [SUPPORTED: https://en.wikipedia.org/wiki/Pye_Road]; Camulodunum was the original Roman provincial capital. [SUPPORTED: https://en.wikipedia.org/wiki/Pye_Road]; Camulodunum was a legionary base. [SUPPORTED: https://en.wikipedia.org/wiki/Pye_Road]; The A140 partly follows the route of Pye Road. [SUPPORTED: https://en.wikipedia.org/wiki/Pye_Road]"}]'::jsonb),
    ('7667ebc2-c948-414d-badd-31dbe04b60c4'::uuid, 'card_description', 'A circular earthwork 27.47 meters across and 2.74 meters high near Babcary, Somerset. Whether it was a Bronze Age bowl barrow (2600–700 BC) or a medieval motte has never been conclusively settled.', 'On a ridgetop near Babcary, Wimble Toot, a burial mound or possibly a motte, overlooks a brook and the old Roman road of the Fosse Way. In Roman times it stood at a crossroads.', 'teaser-card-s009:7667ebc2-c948-414d-badd-31dbe04b60c4:card_description', 'teaser-card-s009 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '20930a781b5b740d7504b2218a6ef1b84355bb4efe3cdcf555ed9659e1a8cbfa|02e308d649fc6344c5fb74e74ab4bd1b9a6eca0df512db99cc585eb044242f6a|02e308d649fc6344c5fb74e74ab4bd1b9a6eca0df512db99cc585eb044242f6a', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a ridgetop near Babcary, Wimble Toot, a burial mound or possibly a motte, overlooks a brook and the old Roman road of the Fosse Way. In Roman times it stood at a crossroads."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Wimble Toot is on a ridgetop [S3]; it is near Babcary [S1]; it is a burial mound or possibly a motte [S1]; it overlooks a brook [S3]; it overlooks the old Roman road of the Fosse Way [S3]; in Roman times it stood at a crossroads [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Wimble Toot is a burial mound (central claim: an earthwork mound) in Somerset, England. [SUPPORTED: https://en.wikipedia.org/wiki/Wimble_Toot]; Wimble Toot is possibly a motte instead (the identification is uncertain). [SUPPORTED: https://en.wikipedia.org/wiki/Wimble_Toot]; Wimble Toot is near the village of Babcary. [SUPPORTED: https://en.wikipedia.org/wiki/Wimble_Toot]; Wimble Toot stands on a ridgetop. [SUPPORTED: https://en.wikipedia.org/wiki/Wimble_Toot]; It overlooks a brook. [SUPPORTED: https://en.wikipedia.org/wiki/Wimble_Toot]; It overlooks the old Roman road of the Fosse Way. [SUPPORTED: https://en.wikipedia.org/wiki/Wimble_Toot]; In Roman times it stood at a crossroads. [SUPPORTED: https://en.wikipedia.org/wiki/Wimble_Toot]"}]'::jsonb),
    ('767b931c-d5d6-4da3-80fd-bdd8b72f8663'::uuid, 'card_description', 'Almost two millennia ago, Romans were extracting stone from the quarry located in the area for the building of Belgrade''s predecessor, Singidunum and for many surviving sarcophagi from that period.', 'Beneath Tašmajdan Park in Belgrade lie caves 6 to 8 million years old, holding remains of a Roman aqueduct. Here the Romans quarried the white limestone for the walls of Singidunum.', 'teaser-card-s009:767b931c-d5d6-4da3-80fd-bdd8b72f8663:card_description', 'teaser-card-s009 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '13956828f0a7c0df287e492763bbc26cb1ae73e2bb7c15832b76c9aad689ff0e|4671bb5a008292bba3b00825d7f16774719f639fcb2e5aa96453f4816ebdd199|4671bb5a008292bba3b00825d7f16774719f639fcb2e5aa96453f4816ebdd199', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Beneath Tašmajdan Park in Belgrade lie caves 6 to 8 million years old, holding remains of a Roman aqueduct. Here the Romans quarried the white limestone for the walls of Singidunum."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "there are caves beneath Tašmajdan Park [S5]; the park is in Belgrade [S1]; the caves are 6 to 8 million years old [S5]; the caves hold remains of a Roman aqueduct [S6]; the Romans quarried stone here [S2]; the stone is white limestone [S4]; the limestone was used for the walls of Singidunum [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Tašmajdan Park is a public park in Belgrade, Serbia (central claim: a park, in Belgrade). [SUPPORTED: https://en.wikipedia.org/wiki/Ta%C5%A1majdan]; Caves lie beneath Tašmajdan Park. [SUPPORTED: https://en.wikipedia.org/wiki/Ta%C5%A1majdan]; The caves are 6 to 8 million years old. [SUPPORTED: https://en.wikipedia.org/wiki/Ta%C5%A1majdan]; The caves hold remains of a Roman aqueduct. [SUPPORTED: https://en.wikipedia.org/wiki/Ta%C5%A1majdan]; The Romans quarried stone at Tašmajdan. [SUPPORTED: https://en.wikipedia.org/wiki/Ta%C5%A1majdan]; The Romans quarried the stone for Singidunum. [SUPPORTED: https://en.wikipedia.org/wiki/Ta%C5%A1majdan]; The stone was white limestone. [SUPPORTED: https://en.wikipedia.org/wiki/Ta%C5%A1majdan]; The white limestone was used for the walls of Singidunum. [SUPPORTED: https://en.wikipedia.org/wiki/Ta%C5%A1majdan]"}]'::jsonb),
    ('768e341f-d9fa-4a3c-a4bf-27d099d7f6da'::uuid, 'card_description', 'A Dacian fortress that became a Roman military post on the Limes Alutanus under Emperor Hadrian. The fortified line ran north-south along the Olt River.', 'On the Olt river near the lower Danube, Acidava grew from a Dacian town into a Roman fort on the Limes Alutanus, a line of fortifications set to watch the Roxolani to the east.', 'teaser-card-s009:768e341f-d9fa-4a3c-a4bf-27d099d7f6da:card_description', 'teaser-card-s009 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '3ac0a6db386414b8a005b336c0d25e236deb83a0833a7376e35856864541d56c|e85976d055ab59a096d73041e96c4bddf3f9d3c5998ff9039ca34d3a722e691c|e85976d055ab59a096d73041e96c4bddf3f9d3c5998ff9039ca34d3a722e691c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the Olt river near the lower Danube, Acidava grew from a Dacian town into a Roman fort on the Limes Alutanus, a line of fortifications set to watch the Roxolani to the east."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Acidava lies on the Olt river [S1]; the river is near the lower Danube [S1]; Acidava was a Dacian town [S1]; it later became a Roman fort (grew from a Dacian town into a Roman town and fort) [S1, S3]; Acidava was part of the Limes Alutanus [S4]; the Limes Alutanus was a line of fortifications [S4]; the limes was set to watch (monitor) the Roxolani [S5]; the Roxolani were to the east [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Acidava is an ancient town and fort site (central claim: what kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Acidava]; Acidava lies on the Olt river [SUPPORTED: https://en.wikipedia.org/wiki/Acidava]; Acidava lies near the lower Danube [SUPPORTED: https://en.wikipedia.org/wiki/Acidava]; The site is in Romania (its remains are at today''s Enoseşti, Olt County) [SUPPORTED: https://en.wikipedia.org/wiki/Acidava]; Acidava was originally a Dacian town [SUPPORTED: https://en.wikipedia.org/wiki/Acidava]; After the Roman conquest Acidava became a military centre in which Roman forts (castra) were built, so the Dacian town grew into a Roman fort site [SUPPORTED: https://en.wikipedia.org/wiki/Acidava]; There was a Roman fort at Acidava [SUPPORTED: https://en.wikipedia.org/wiki/Acidava_(castra)]; Acidava lay on the Limes Alutanus [SUPPORTED: https://en.wikipedia.org/wiki/Acidava]; The Limes Alutanus is a line of fortifications [SUPPORTED: https://en.wikipedia.org/wiki/Acidava]; The limes was set to watch (monitor) the Roxolani [SUPPORTED: https://en.wikipedia.org/wiki/Acidava]; The Roxolani were to the east of the limes [SUPPORTED: https://en.wikipedia.org/wiki/Acidava]"}]'::jsonb),
    ('768e4ff5-0271-43a3-b40e-a2e7b99444b3'::uuid, 'card_description', 'An island sacred to both Apollo and Artemis, considered the center of the Cyclades. Excavations here are among the most extensive in the entire Mediterranean.', 'The Roman Republic ceded Delos to the Athenians in 167 or 166 BC. After Rome destroyed Corinth in 146 BC, Delos at least partially assumed its role as premier trading centre of Greece.', 'teaser-card-s009:768e4ff5-0271-43a3-b40e-a2e7b99444b3:card_description', 'teaser-card-s009 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '11a67bf67762f97227aa53f97452188f8edfedcda9b3e0d7da977e51e88422e9|3539aa3f92c82b709be24162f4cf2a81ad2bdd45887fc4e776c24c4eca38ff0a|3539aa3f92c82b709be24162f4cf2a81ad2bdd45887fc4e776c24c4eca38ff0a', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Roman Republic ceded Delos to the Athenians in 167 or 166 BC. After Rome destroyed Corinth in 146 BC, Delos at least partially assumed its role as premier trading centre of Greece."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Roman Republic ceded Delos to the Athenians [S4]; this happened in 167 or 166 BC [S4]; Rome destroyed Corinth in 146 BC [S5]; after that, Delos at least partially assumed Corinth''s role as the premier trading centre of Greece [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Delos is a small Greek island (archaeological site and ancient trading centre) in the Cyclades [SUPPORTED: https://en.wikipedia.org/wiki/Delos]; The Roman Republic ceded Delos to the Athenians in 167 or 166 BC [SUPPORTED: https://en.wikipedia.org/wiki/Delos]; Rome destroyed Corinth in 146 BC [SUPPORTED: https://en.wikipedia.org/wiki/Delos]; After the destruction of Corinth, Delos at least partially assumed its role as premier trading centre of Greece [SUPPORTED: https://en.wikipedia.org/wiki/Delos]"}]'::jsonb),
    ('77133f15-f416-449a-b991-ac9f41505a88'::uuid, 'card_description', 'A Roman crossroads town where multiple major roads converged, including the Via Traiana. Its Latin name means "flat plain" — a rare honest name for a Roman town.', 'Near where the Via Minucia met the Via Aemilia in Hirpinis, Cicero knew Aequum Tuticum as a regular stop on the road to Apulia. Digs found walls, inscriptions, funerary steles and coins.', 'teaser-card-s009:77133f15-f416-449a-b991-ac9f41505a88:card_description', 'teaser-card-s009 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '4bca2a003596c8179db464a266be5ad5d560da7db0088025eda5239155c1135d|831ac78b51c35f224bc9d7e847cd59cb66fb2b6f5fcbbe59bdca2a969fbfaf37|831ac78b51c35f224bc9d7e847cd59cb66fb2b6f5fcbbe59bdca2a969fbfaf37', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Near where the Via Minucia met the Via Aemilia in Hirpinis, Cicero knew Aequum Tuticum as a regular stop on the road to Apulia. Digs found walls, inscriptions, funerary steles and coins."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is near where the Via Minucia met the Via Aemilia in Hirpinis [S2]; Cicero described Aequum Tuticum [S3]; Aequum Tuticum was a regular stopping point on the route to Apulia [S3]; excavations were carried out [S4]; the excavations found walls [S4]; the excavations found inscriptions [S4]; the excavations found funerary steles [S4]; the excavations found coins [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Aequum Tuticum was a Roman settlement (a vicus) at a road junction in southern Italy, in the Irpinia region near Ariano Irpino (central claim: what kind of place, and where) [SUPPORTED: https://en.wikipedia.org/wiki/Aequum_Tuticum]; Aequum Tuticum lay near the intersection of two ancient Roman roads (where the Via Minucia met the Via Aemilia in Hirpinis) [SUPPORTED: https://en.wikipedia.org/wiki/Aequum_Tuticum]; One of the two roads meeting there was the Via Minucia [SUPPORTED: https://en.wikipedia.org/wiki/Aequum_Tuticum]; The other road meeting there was the Via Aemilia in Hirpinis [SUPPORTED: https://en.wikipedia.org/wiki/Aequum_Tuticum]; Cicero knew the place (he mentions it in a letter of 50 BC) [SUPPORTED: https://en.wikipedia.org/wiki/Aequum_Tuticum]; Cicero knew it as a regular stop [SUPPORTED: https://en.wikipedia.org/wiki/Aequum_Tuticum]; The regular stop lay on the road to Apulia [SUPPORTED: https://en.wikipedia.org/wiki/Aequum_Tuticum]; Excavations found walls [SUPPORTED: https://en.wikipedia.org/wiki/Aequum_Tuticum]; Excavations found inscriptions [SUPPORTED: https://en.wikipedia.org/wiki/Aequum_Tuticum]; Excavations found funerary steles [SUPPORTED: https://en.wikipedia.org/wiki/Aequum_Tuticum]; Excavations found coins [SUPPORTED: https://en.wikipedia.org/wiki/Aequum_Tuticum]"}]'::jsonb),
    ('775adc1b-7af2-4452-824b-5cc575b2ec8c'::uuid, 'card_description', 'An ancient settlement absorbed into the modern capital in 1934. Its strategic position on the Danube made it a contested border town for centuries.', 'Zemun has been inhabited since the Neolithic; Baden culture graves and anthropomorphic urns were found in the town. The Celtic Scordisci founded Taurunum and, across the Sava, Singidunum.', 'teaser-card-s009:775adc1b-7af2-4452-824b-5cc575b2ec8c:card_description', 'teaser-card-s009 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'ca164672c7e190d9fc923dae29841b31ede79208c63c958eea872fb1c3dd4c7c|7a1758df7201712de3446d32dc63a3db5b96f56993a692bb252a8bc5ea094b39|7a1758df7201712de3446d32dc63a3db5b96f56993a692bb252a8bc5ea094b39', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Zemun has been inhabited since the Neolithic; Baden culture graves and anthropomorphic urns were found in the town. The Celtic Scordisci founded Taurunum and, across the Sava, Singidunum."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Zemun has been inhabited since the Neolithic [S1]; Baden culture graves were found in the town [S2]; anthropomorphic urns were found in the town [S2]; the Scordisci were Celtic [S3]; the Scordisci founded Taurunum [S4]; the Scordisci founded Singidunum [S4]; Singidunum lies across the Sava [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Zemun is a town in Serbia, formerly separate and now a municipality of Belgrade (central claim: what kind of place, and where) [SUPPORTED: https://en.wikipedia.org/wiki/Zemun]; Zemun has been inhabited since the Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Zemun]; Baden culture graves were found in the town [SUPPORTED: https://en.wikipedia.org/wiki/Zemun]; Anthropomorphic urns were found in the town [SUPPORTED: https://en.wikipedia.org/wiki/Zemun]; The ancient settlement at Zemun was Taurunum [SUPPORTED: https://en.wikipedia.org/wiki/Zemun]; The Scordisci were a Celtic tribe [SUPPORTED: https://en.wikipedia.org/wiki/Singidunum]; The Scordisci founded Taurunum and, across the Sava, Singidunum [SUPPORTED: https://en.wikipedia.org/wiki/Zemun]; The Scordisci are credited with founding Singidunum (predecessor of modern Belgrade) [SUPPORTED: https://en.wikipedia.org/wiki/Singidunum]"}]'::jsonb),
    ('77dfbcdc-7370-4159-a5ee-a6ba39c0aed6'::uuid, 'card_description', 'A Neolithic burial chamber from around 3000 BC, also known as "Arthur''s Quoit." Its passage grave retains a round barrow form despite millennia of erosion.', 'On a hillside near St Davids Head lies the Coetan Arthur Dolmen, a collapsed Neolithic burial chamber of around 3000 BC, its massive capstone propped on one side by an upright stone.', 'teaser-card-s009:77dfbcdc-7370-4159-a5ee-a6ba39c0aed6:card_description', 'teaser-card-s009 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '95d4fbea7b24748ea37d970fa7dd434d452c7bcd4b0155834342cca9339dc912|ab6955fe1540e9fe67b4e179b321108742be85b18f145631d4a7ea1fb56a68b4|ab6955fe1540e9fe67b4e179b321108742be85b18f145631d4a7ea1fb56a68b4', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a hillside near St Davids Head lies the Coetan Arthur Dolmen, a collapsed Neolithic burial chamber of around 3000 BC, its massive capstone propped on one side by an upright stone."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the dolmen is on a hillside [S3]; it is near St Davids Head [S3]; it is a burial chamber [S1, S3]; it is Neolithic [S1]; it is collapsed [S3]; it dates to around 3000 BC [S2]; it has a massive capstone [S4]; the capstone is supported on one side by an upright stone (orthostat) [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Coetan Arthur Dolmen is a Neolithic burial chamber (central claim: what kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Coetan_Arthur]; It is a dolmen (chambered tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Coetan_Arthur]; It lies near St Davids Head [SUPPORTED: https://en.wikipedia.org/wiki/Coetan_Arthur]; It lies on a hillside [SUPPORTED: https://en.wikipedia.org/wiki/Coetan_Arthur]; The chamber is collapsed [SUPPORTED: https://en.wikipedia.org/wiki/Coetan_Arthur]; The monument is Neolithic in date [SUPPORTED: https://coflein.gov.uk/en/site/305375/]; It dates from around 3000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Coetan_Arthur]; It has a massive capstone [SUPPORTED: https://en.wikipedia.org/wiki/Coetan_Arthur]; The capstone is propped on one side by an upright stone (orthostat) [SUPPORTED: https://en.wikipedia.org/wiki/Coetan_Arthur]; The capstone is supported by an orthostat at one end [SUPPORTED: https://coflein.gov.uk/en/site/305375/]"}]'::jsonb),
    ('77e3f3a1-163d-4925-88c5-86456fc81dd7'::uuid, 'card_description', 'Home to roughly 3,000 people on the right Danube bank in the 3rd millennium BC, this site lent its name to the entire Vučedol culture — a label now applied to sites across a wide swath of Europe.', 'Roughly 5 kilometres downstream from Vukovar, Vučedol gave its name to the eneolithic Vučedol culture. Once home to about 3,000 people, it has also yielded Baden and Kostolac finds.', 'teaser-card-s009:77e3f3a1-163d-4925-88c5-86456fc81dd7:card_description', 'teaser-card-s009 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '706f8854af8c8e00a0acafc73a55e89386ce348a02daa38a4314015d10682aaf|6cf7d7fd9be47bc0e2de8aace4d69b99610d46e7884a74d04fd1cefe0509805b|6cf7d7fd9be47bc0e2de8aace4d69b99610d46e7884a74d04fd1cefe0509805b', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Roughly 5 kilometres downstream from Vukovar, Vučedol gave its name to the eneolithic Vučedol culture. Once home to about 3,000 people, it has also yielded Baden and Kostolac finds."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies roughly 5 kilometres downstream from Vukovar [S5]; Vučedol gave its name to the Vučedol culture [S1]; the Vučedol culture is eneolithic [S1]; the site was once home to about 3,000 people (an approximate figure) [S2]; finds of the Baden culture have been confirmed at the site [S4]; finds of the Kostolac culture have been confirmed at the site [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Vučedol is an archaeological site (a settlement site on the Danube) in Croatia [SUPPORTED: https://en.wikipedia.org/wiki/Vu%C4%8Dedol]; Vučedol lies roughly 5 kilometres downstream from Vukovar [SUPPORTED: https://en.wikipedia.org/wiki/Vu%C4%8Dedol]; Vučedol gave its name to the Vučedol culture [SUPPORTED: https://en.wikipedia.org/wiki/Vu%C4%8Dedol]; The Vučedol culture is eneolithic [SUPPORTED: https://en.wikipedia.org/wiki/Vu%C4%8Dedol]; The site was once home to about 3,000 people [SUPPORTED: https://en.wikipedia.org/wiki/Vu%C4%8Dedol]; Baden culture finds have been made at Vučedol [SUPPORTED: https://en.wikipedia.org/wiki/Vu%C4%8Dedol]; Kostolac culture finds have been made at Vučedol [SUPPORTED: https://en.wikipedia.org/wiki/Vu%C4%8Dedol]"}]'::jsonb),
    ('77eab45e-3a34-4ebd-abb0-ac6431b72b42'::uuid, 'card_description', 'Univallate fort at 228 metres spanning two parish boundaries near Donhead St Mary. A scheduled monument on Upper Greensand sandstone beds, with metal-detector finds recorded from the 1980s.', 'Four gaps pierce the ramparts of Castle Rings, an Iron Age hill fort, and it is not known if they were its original entrances. In 1985 a detectorist dug up 88 coins of the Durotriges here.', 'teaser-card-s009:77eab45e-3a34-4ebd-abb0-ac6431b72b42:card_description', 'teaser-card-s009 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '3af2884f4fcf53aac9cce0010d056ce0aa9c130aa3590ff875c2d77576e3574a|ee1b534e27511faa9356d082b3d2776598941e9a716d7c7aea0e57274d26b09d|ee1b534e27511faa9356d082b3d2776598941e9a716d7c7aea0e57274d26b09d', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Four gaps pierce the ramparts of Castle Rings, an Iron Age hill fort, and it is not known if they were its original entrances. In 1985 a detectorist dug up 88 coins of the Durotriges here."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "there are four gaps in the ramparts of Castle Rings [S6]; Castle Rings is a hill fort [S1]; Castle Rings dates to the Iron Age [S2]; it is not known whether the four gaps were original entrances to the fort [S6]; in 1985 a detectorist dug up coins at the fort [S3, S8]; 88 coins were found [S8]; the coins are of the Durotriges [S3, S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Castle Rings is a hill fort in Wiltshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Rings,_Wiltshire]; Castle Rings is Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Rings,_Wiltshire]; Four gaps pierce the ramparts of Castle Rings [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Rings,_Wiltshire]; It is not known if the four gaps were the fort''s original entrances [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Rings,_Wiltshire]; A metal detectorist dug up coins at Castle Rings in 1985 [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Rings,_Wiltshire]; 88 coins were found [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Rings,_Wiltshire]; The coins are attributed to the Durotriges [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Rings,_Wiltshire]"}]'::jsonb),
    ('788f9236-c12f-4f94-9dc6-4f3a3d682626'::uuid, 'card_description', 'A 2nd-century AD Roman sanctuary with cavities of various sizes carved into three large cliffs. Steps cut into the rock lead to ritual platforms.', 'Santuário Rupestre de Panóias is an enclosure of three large rocks with cavities opened in them and stairs built. On the entrance rock, Latin and Greek inscriptions describe the ritual.', 'teaser-card-s009:788f9236-c12f-4f94-9dc6-4f3a3d682626:card_description', 'teaser-card-s009 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'fb3f0b14b91252fc3b1c21563436109d6269a47c2cc6b24444a2e71af1e19f92|d88e3c16abca5e706340bc3f34d85aad71ff13cbaa38f1af721bbfa86ab93b94|d88e3c16abca5e706340bc3f34d85aad71ff13cbaa38f1af721bbfa86ab93b94', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Santuário Rupestre de Panóias is an enclosure of three large rocks with cavities opened in them and stairs built. On the entrance rock, Latin and Greek inscriptions describe the ritual."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the sanctuary is an enclosure of three large rocks [S3]; cavities were opened in the rocks [S3]; stairs were built [S3]; inscriptions are on the rock at the entrance [S4]; the inscriptions are in Latin and Greek [S4]; the inscriptions describe the ritual [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Panóias rock sanctuary (Santuário Rupestre de Panóias) is a sanctuary in Portugal (Vila Real) [SUPPORTED: https://en.wikipedia.org/wiki/Panoias_Sanctuary]; The sanctuary is an enclosure of three large rocks [SUPPORTED: https://en.wikipedia.org/wiki/Panoias_Sanctuary]; Cavities were opened in the rocks [SUPPORTED: https://en.wikipedia.org/wiki/Panoias_Sanctuary]; Stairs were built at the sanctuary [SUPPORTED: https://en.wikipedia.org/wiki/Panoias_Sanctuary]; The inscriptions are on the rock at the entrance of the enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Panoias_Sanctuary]; The inscriptions are in Latin and Greek [SUPPORTED: https://en.wikipedia.org/wiki/Panoias_Sanctuary]; The inscriptions describe the ritual [SUPPORTED: https://en.wikipedia.org/wiki/Panoias_Sanctuary]"}]'::jsonb),
    ('78c3716d-79fb-46aa-82df-3a26d8ffd414'::uuid, 'card_description', 'A site of the El Argar culture (2200-1500 BC), which controlled territory the size of Belgium. An exceptionally rich female burial hints at women holding power.', 'At La Almoloya, a woman and a man lie beneath the floor of a large building, their grave holding numerous silver goods including a diadem. Radiocarbon dating suggests approximately 1700 BC.', 'teaser-card-s009:78c3716d-79fb-46aa-82df-3a26d8ffd414:card_description', 'teaser-card-s009 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'ec7b3a60afca47817999d8dfedb6ffc122c1adb93168f60d4d3caab4d82c53bb|26ed993765dcd5386fe4411c95555c9e9463c2ff856b869f6299518eb4932e82|26ed993765dcd5386fe4411c95555c9e9463c2ff856b869f6299518eb4932e82', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At La Almoloya, a woman and a man lie beneath the floor of a large building, their grave holding numerous silver goods including a diadem. Radiocarbon dating suggests approximately 1700 BC."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "a woman and a man lie in the grave [S4]; they lie beneath the floor of a large building [S6]; the grave holds numerous silver goods [S5]; the goods include a diadem [S5]; radiocarbon dating suggests approximately 1700 BC [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "La Almoloya is an archaeological site in Spain (Murcia, southeast Iberia) [SUPPORTED: https://en.wikipedia.org/wiki/La_Almoloya]; A woman and a man are buried together in one grave at La Almoloya [SUPPORTED: https://www.nationalgeographic.com/history/article/ancient-woman-powerful-european-leader-4000-year-old-treasure-suggests]; The couple lies beneath the floor of a building [SUPPORTED: https://en.wikipedia.org/wiki/La_Almoloya]; The building above the grave is large [SUPPORTED: https://en.wikipedia.org/wiki/La_Almoloya]; The grave holds numerous silver goods [SUPPORTED: https://en.wikipedia.org/wiki/La_Almoloya]; The grave goods include a diadem [SUPPORTED: https://www.nationalgeographic.com/history/article/ancient-woman-powerful-european-leader-4000-year-old-treasure-suggests]; Radiocarbon dating suggests the burial dates to approximately 1700 BC [SUPPORTED: https://www.nationalgeographic.com/history/article/ancient-woman-powerful-european-leader-4000-year-old-treasure-suggests]"}]'::jsonb),
    ('79132373-7a68-45e3-a174-3b1e429a12b3'::uuid, 'card_description', 'Northernmost tip of the peninsula, where Phoenician salt fish factory ruins and a Phoenician port survive. A lighthouse raised in 1850 still operates on the same headland.', NULL, 'teaser-card-s009:79132373-7a68-45e3-a174-3b1e429a12b3:card_description', 'teaser-card-s009 (card-clear-contradicted-after-verify): card cleared (contradicted-after-verify)', '||efb27e6a18427e66579e8fb88480365a850f1cf532b9178b5a86d045335b57bd', '[{"source": "lane WB run wb-ws-2026-09-27-04: contradicted-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The web check contradicts: It receives more than 2500 mm of rain a year (https://de.wikipedia.org/wiki/Estaca_de_Bares: \"Niederschlagsmenge von etwa 1500 mm pro Jahr gehört es zu den regenreichsten Orten Europas\"); The web check contradicts: There are ruins of a Phoenician port at Estaca de Bares (https://es.wikipedia.org/wiki/Puerto_de_Bares: \"Federico Maciñeira le llegó a atribuir orígenes fenicios, si bien esta hipótesis pareciera haber quedado descartada por autores más recientes\"); The web check could not prove: There are ruins of a Phoenician salt fish factory at Estaca de Bares; The web check contradicts: It receives about 1500 mm of rain a year (https://en.wikipedia.org/wiki/Punta_de_Estaca_de_Bares: \"it is one of the rainiest places in Europe, with more than 2500 mm a year\")"}]'::jsonb),
    ('7aa50e78-6ede-4901-b2a3-155f842ca0e2'::uuid, 'card_description', 'A Roman quarry worked around 200 AD by the 22nd Legion. Soldiers left inscriptions and carvings in the sandstone they extracted from this forested hillside.', 'On the Kästenberg, the Kriemhildenstuhl was quarried by several working parties called Arbeitsköpfe, individual ones 25 metres above the next level below. Excavations ran in 1884 and later.', 'teaser-card-s009:7aa50e78-6ede-4901-b2a3-155f842ca0e2:card_description', 'teaser-card-s009 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '72442b0f46f50ea1b6b9895235cefebea562da936d2a5688f7a96b1581a962ba|1e3cf2c9cb78de320421cb618b6821336293034eb55f55570777f8b049a6ed30|1e3cf2c9cb78de320421cb618b6821336293034eb55f55570777f8b049a6ed30', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the Kästenberg, the Kriemhildenstuhl was quarried by several working parties called Arbeitsköpfe, individual ones 25 metres above the next level below. Excavations ran in 1884 and later."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies on the Kästenberg [S1]; it was quarried by several working parties [S3]; the working parties are called Arbeitsköpfe [S3]; individual Arbeitsköpfe were 25 metres above the next level below [S4]; excavations were carried out in 1884 and later [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Kriemhildenstuhl is a quarry (a former Roman quarry), the site type on which the whole text rests [SUPPORTED: https://de.wikipedia.org/wiki/Kriemhildenstuhl]; The Kriemhildenstuhl lies on the Kästenberg [SUPPORTED: https://de.wikipedia.org/wiki/Kriemhildenstuhl]; It was quarried by several working parties called Arbeitsköpfe [SUPPORTED: https://de.wikipedia.org/wiki/Kriemhildenstuhl]; Individual Arbeitsköpfe were 25 metres above the next level below [SUPPORTED: https://de.wikipedia.org/wiki/Kriemhildenstuhl]; Excavations ran in 1884 and later [SUPPORTED: https://de.wikipedia.org/wiki/Kriemhildenstuhl]"}]'::jsonb),
    ('7d711cde-9765-499f-a664-0409651a90e8'::uuid, 'card_description', 'A Buddhist rock-cut hillock covered with monolithic stupas surrounding a great central platform. The dome of the main stupa was built of brick atop the carved stone.', 'Bojjanna Konda, once called Buddina Konda, and its neighbouring hill hold monolithic stupas, rock-cut caves, chaityas and monasteries, believed founded between the 4th and 9th centuries AD.', 'teaser-card-s009:7d711cde-9765-499f-a664-0409651a90e8:card_description', 'teaser-card-s009 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '2e005629c17343cd0cc680cf6a7b8e207d0f6c6fa50adea78a50cd8b14984380|26f0373fb4b6c47d778bd2556c7f7d57297d3fd888ffef007d420f1ba315131c|26f0373fb4b6c47d778bd2556c7f7d57297d3fd888ffef007d420f1ba315131c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Bojjanna Konda, once called Buddina Konda, and its neighbouring hill hold monolithic stupas, rock-cut caves, chaityas and monasteries, believed founded between the 4th and 9th centuries AD."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Bojjanna Konda was once called Buddina Konda [S3]; it has a neighbouring hill [S1, S5]; the hills hold monolithic stupas [S6]; the hills hold rock-cut caves [S1, S6]; the hills hold chaityas [S6]; the hills hold monasteries [S6]; the sites are believed to have been founded between the 4th and 9th centuries AD [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Bojjanna Konda is a hill site of Buddhist rock-cut caves, stupas and monasteries (a Buddhist monastic complex on a hill) [SUPPORTED: https://en.wikipedia.org/wiki/Bojjannakonda]; Bojjanna Konda was originally called Buddina Konda [SUPPORTED: https://en.wikipedia.org/wiki/Bojjannakonda]; Bojjanna Konda has a neighbouring hill (Lingalakonda) that belongs to the same complex [SUPPORTED: https://en.wikipedia.org/wiki/Bojjannakonda]; The hills hold monolithic stupas [SUPPORTED: https://en.wikipedia.org/wiki/Bojjannakonda]; The hills hold rock-cut caves [SUPPORTED: https://en.wikipedia.org/wiki/Bojjannakonda]; The hills hold chaityas [SUPPORTED: https://en.wikipedia.org/wiki/Bojjannakonda]; The hills hold monasteries [SUPPORTED: https://en.wikipedia.org/wiki/Bojjannakonda]; The sites are believed to have been founded between the 4th and 9th centuries AD [SUPPORTED: https://en.wikipedia.org/wiki/Bojjannakonda]"}]'::jsonb),
    ('7e2b3ee7-ffb0-40d3-ae9d-7c8044dd42d2'::uuid, 'card_description', 'A city at the confluence of three rivers, once a Roman colony called Batavis. The Boii Celts established a settlement here after being driven north from Italy.', 'Passau was once Batavis, a Roman castrum in Raetia named for the Batavi, while the late Roman castrum of Boiotro stood in Noricum. In the 5th century St. Severinus founded a monastery here.', 'teaser-card-s009:7e2b3ee7-ffb0-40d3-ae9d-7c8044dd42d2:card_description', 'teaser-card-s009 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '3c64b04a2175bbea9e94db5c95a61cba53ef570259bffd74b8470bfacbade577|46ecc5e0514e6da3bb14a57ea3e20d2168f6df6751db2d8b010cefadb6213a45|46ecc5e0514e6da3bb14a57ea3e20d2168f6df6751db2d8b010cefadb6213a45', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Passau was once Batavis, a Roman castrum in Raetia named for the Batavi, while the late Roman castrum of Boiotro stood in Noricum. In the 5th century St. Severinus founded a monastery here."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Passau was once called Batavis [S1]; Batavis was a Roman castrum [S2]; Batavis was in the province of Raetia [S2]; Batavis was named for the Batavi [S1]; Boiotro was a late Roman castrum [S2]; Boiotro was in the province of Noricum [S2]; in the 5th century St. Severinus founded a monastery at Passau [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Passau is the site of the Roman castrum Batavis: Passau was once Batavis, a Roman castrum [SUPPORTED: https://en.wikipedia.org/wiki/Passau]; Passau was once called Batavis [SUPPORTED: https://en.wikipedia.org/wiki/Passau]; Batavis was a Roman castrum (fort) [SUPPORTED: https://en.wikipedia.org/wiki/Passau]; Batavis lay in the province of Raetia [SUPPORTED: https://en.wikipedia.org/wiki/Passau]; Batavis was named for the Batavi [SUPPORTED: https://en.wikipedia.org/wiki/Passau]; There was a late Roman castrum called Boiotro [SUPPORTED: https://en.wikipedia.org/wiki/Passau]; The late Roman castrum of Boiotro stood in the province of Noricum [SUPPORTED: https://en.wikipedia.org/wiki/Passau]; St. Severinus founded a monastery at Passau [SUPPORTED: https://en.wikipedia.org/wiki/Passau]; The monastery was founded in the 5th century [SUPPORTED: https://en.wikipedia.org/wiki/Passau]"}]'::jsonb),
    ('7e45502b-80d5-404a-9b46-cfd630d2be3a'::uuid, 'card_description', 'A Maya cave where pottery and human remains were placed on ledges deep inside. The Maya treated caves as entrances to Xibalba, the underworld of the dead.', 'In the early 1970s Mennonites floated on oil drums into Barton Creek Cave and found human bones not far from its entrance. By 2005 the survey of its stream passages had reached 8 km.', 'teaser-card-s009:7e45502b-80d5-404a-9b46-cfd630d2be3a:card_description', 'teaser-card-s009 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'ac1f7c60b1b14db60fed083aab7009d9c288a2d36442839e9cc9059ffeda615f|c7d81fb1cab4d0001e9448961fa6c7c9f8d0246d66a0dc97a1b036a23314191f|c7d81fb1cab4d0001e9448961fa6c7c9f8d0246d66a0dc97a1b036a23314191f', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In the early 1970s Mennonites floated on oil drums into Barton Creek Cave and found human bones not far from its entrance. By 2005 the survey of its stream passages had reached 8 km."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "in the early 1970s Mennonites floated into Barton Creek Cave [S6]; they floated on oil drums [S6]; they found human bones [S7]; the bones were not far from the cave entrance [S7]; by 2005 the survey of the cave had reached 8 km [S5]; the surveyed passages are stream passages (a stream cave) [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Barton Creek Cave is a natural stream cave in Belize, an archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Barton_Creek_Cave]; In the early 1970s Mennonites entered Barton Creek Cave [SUPPORTED: https://en.wikipedia.org/wiki/Barton_Creek_Cave]; The Mennonites floated on oil drums into the cave [SUPPORTED: https://en.wikipedia.org/wiki/Barton_Creek_Cave]; They found human bones [SUPPORTED: https://en.wikipedia.org/wiki/Barton_Creek_Cave]; The human bones lay not far from the cave entrance [SUPPORTED: https://en.wikipedia.org/wiki/Barton_Creek_Cave]; By 2005 the survey of its stream passages had reached 8 km [SUPPORTED: https://en.wikipedia.org/wiki/Barton_Creek_Cave]; The cave is a stream cave (its passages carry a stream) [SUPPORTED: https://en.wikipedia.org/wiki/Barton_Creek_Cave]"}]'::jsonb),
    ('7e6261c5-5292-4019-8a1b-5860a37714f9'::uuid, 'card_description', 'Overlooking the ancient crossing of the River Barle, this oval fort stretches 220 by 91 metres with bank, ditch, and rampart. It lies near the Devon border north of Dulverton.', 'Above Dulverton and the ancient crossing of the River Barle, the Iron Age hill fort of Oldberry Castle forms an irregular oval, defended by a bank and an 18 feet wide ditch.', 'teaser-card-s009:7e6261c5-5292-4019-8a1b-5860a37714f9:card_description', 'teaser-card-s009 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', '3d88fdd3f8841e43d1af2eeef16a240131d68c3e932145830935469913afa075|5ff9d9846edf394136a947e296360d41a204618f8dfbd513cb414dec2e87928c|5ff9d9846edf394136a947e296360d41a204618f8dfbd513cb414dec2e87928c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Above Dulverton and the ancient crossing of the River Barle, the Iron Age hill fort of Oldberry Castle forms an irregular oval, defended by a bank and an 18 feet wide ditch."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies above (overlooks) Dulverton [S4]; it overlooks the ancient crossing of the River Barle [S4]; Oldberry Castle is an Iron Age hill fort [S1]; it forms an irregular oval [S5]; it is defended by a bank [S6]; it is defended by an 18 feet wide ditch [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Oldberry Castle is an Iron Age hill fort at Dulverton, Somerset, England [SUPPORTED: https://en.wikipedia.org/wiki/Oldberry_Castle]; The fort lies above (overlooks) Dulverton [SUPPORTED: https://en.wikipedia.org/wiki/Oldberry_Castle]; The fort overlooks the ancient crossing of the River Barle [SUPPORTED: https://en.wikipedia.org/wiki/Oldberry_Castle]; The fort forms an irregular oval [SUPPORTED: https://en.wikipedia.org/wiki/Oldberry_Castle]; It is defended by a bank [SUPPORTED: https://en.wikipedia.org/wiki/Oldberry_Castle]; The ditch is 18 feet wide [SUPPORTED: https://en.wikipedia.org/wiki/Oldberry_Castle]"}]'::jsonb),
    ('7e79ddfa-87b6-4b1f-bbfc-0a0772e3946d'::uuid, 'card_description', 'An ancient Greek colony from the 3rd century BC, later refounded as Blanda Julia by the Romans. Pliny and Strabo both mentioned it, though they disagreed on its exact location.', 'Ancient City of Blanda: in the 4th century BC Lucanians rebuilt a village on Palècastro hill and fortified it with a wall. A necropolis was established between San Brancato and Palècastro.', 'teaser-card-s009:7e79ddfa-87b6-4b1f-bbfc-0a0772e3946d:card_description', 'teaser-card-s009 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'ba6408f01f80949e849586736e53c56fbedbf39bd8b7f5674b1b7ed4b05d80c9|7c30e9caef5d54f0391f6c6f6a12760c9ddc03404a76e7a6a1c423b5b20a5815|7c30e9caef5d54f0391f6c6f6a12760c9ddc03404a76e7a6a1c423b5b20a5815', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Ancient City of Blanda: in the 4th century BC Lucanians rebuilt a village on Palècastro hill and fortified it with a wall. A necropolis was established between San Brancato and Palècastro."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "in the 4th century BC Lucanians occupied Palècastro hill and rebuilt a village there [S2]; they fortified it with a wall [S2]; a necropolis was established [S3]; the necropolis lies in the area between San Brancato and Palècastro [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-045 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Blanda is an ancient city (a settlement) in Italy, at Palecastro di Tortora [SUPPORTED: https://en.wikipedia.org/wiki/Blanda_Julia]; In the 4th century BC the Lucanians occupied the Palècastro hill and rebuilt the village there [SUPPORTED: https://en.wikipedia.org/wiki/Blanda_Julia]; The Lucanians fortified the rebuilt village with a wall [SUPPORTED: https://en.wikipedia.org/wiki/Blanda_Julia]; A necropolis was established between San Brancato and Palècastro [SUPPORTED: https://en.wikipedia.org/wiki/Blanda_Julia]"}]'::jsonb),
    ('7ef03e67-8439-4a61-84ab-c5e92424e17a'::uuid, 'card_description', 'Caudini city near the frontier of Campania, attacked by Rome during the First Samnite War in 343 BC. Ceramic evidence shows Saticula was part of a regional trade network along the Volturno River.', 'In 343 BC the Roman consul Cornelius attacked Saticula, a Caudini city near the frontier of Campania. Its pottery suggests a trade network along the Volturno River to the Tyrrhenian Sea.', 'teaser-card-s009:7ef03e67-8439-4a61-84ab-c5e92424e17a:card_description', 'teaser-card-s009 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '049dee974121aa79554c5509479a07e7b224a93bd75ccb91dc115fc19c3174df|e130ff0fcd322f7b7e4450619543f61a2c25d679f891bb27b5b0cc904399a9a0|e130ff0fcd322f7b7e4450619543f61a2c25d679f891bb27b5b0cc904399a9a0', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In 343 BC the Roman consul Cornelius attacked Saticula, a Caudini city near the frontier of Campania. Its pottery suggests a trade network along the Volturno River to the Tyrrhenian Sea."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "in 343 BC the Roman consul Cornelius attacked Saticula [S2]; Saticula was a Caudini city [S1]; it was near the frontier of Campania [S1]; its pottery suggests a trade network along the Volturno River [S4]; the network reached to the Tyrrhenian Sea [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-045 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Saticula was a city of the Caudini [SUPPORTED: https://en.wikipedia.org/wiki/Saticula]; Saticula lay near the frontier of Campania [SUPPORTED: https://en.wikipedia.org/wiki/Saticula]; The attack on Saticula took place in 343 BC [SUPPORTED: https://en.wikipedia.org/wiki/Saticula]; The Roman consul Cornelius attacked Saticula [SUPPORTED: https://en.wikipedia.org/wiki/Saticula]; Pottery (ceramic evidence) from Saticula suggests a trade network along the Volturno River [SUPPORTED: https://en.wikipedia.org/wiki/Saticula]; The Volturno trade network reached the Tyrrhenian Sea [SUPPORTED: https://en.wikipedia.org/wiki/Saticula]"}]'::jsonb),
    ('7efae859-7199-4dd9-bde0-fcee0163a19e'::uuid, 'card_description', 'Thracian cult plateau in the Rhodopes carved with round holes, stepped trails, and niches. Evidence points to a sanctuary of the Bessi tribe dedicated to the god Sabazios.', 'The rock plateau of Belintash, on the Dobrostan ridge of the Rhodopes, bears traces of human activity; its sinking rock formed three areas. Archaeologists first studied it in 1975.', 'teaser-card-s009:7efae859-7199-4dd9-bde0-fcee0163a19e:card_description', 'teaser-card-s009 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '15aded284adb94d28cb508aead5713c2ab0e725c55e78187fef75a31499bebb3|239d835145cf64c4e508b1df85bcbc19b69ad9bd23f79a3badbd41bf604e3a9b|239d835145cf64c4e508b1df85bcbc19b69ad9bd23f79a3badbd41bf604e3a9b', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The rock plateau of Belintash, on the Dobrostan ridge of the Rhodopes, bears traces of human activity; its sinking rock formed three areas. Archaeologists first studied it in 1975."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Belintash is a rock plateau [S1, S3]; it lies on the Dobrostan ridge of the Rhodopes [S2]; it bears traces of human activity [S1]; the sinking of the rock formed three areas on the plateau [S4]; archaeologists first studied it in 1975 [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-045 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Belintash is a rock plateau in the Rhodope Mountains, Bulgaria [SUPPORTED: https://en.wikipedia.org/wiki/Belintash]; Belintash lies on the Dobrostan ridge of the Rhodopes [SUPPORTED: https://en.wikipedia.org/wiki/Belintash]; The plateau bears traces of human activity [SUPPORTED: https://en.wikipedia.org/wiki/Belintash]; The sinking of the rock formed three areas on the plateau [SUPPORTED: https://en.wikipedia.org/wiki/Belintash]; Archaeologists first studied Belintash in 1975 [SUPPORTED: https://en.wikipedia.org/wiki/Belintash]"}]'::jsonb),
    ('7f7fe84f-3bf8-415b-af7b-c6c95333807a'::uuid, 'card_description', 'The Neolithic Dwellings Museum is built around two Neolithic houses dating back to the 6th millennium BC.', 'In Stara Zagora, the Neolithic Dwellings Museum shelters two houses of the 6th millennium BC, the best-preserved of their period in Europe, with kitchens, fireplaces and hand grain mills.', 'teaser-card-s009:7f7fe84f-3bf8-415b-af7b-c6c95333807a:card_description', 'teaser-card-s009 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '5256db39c7749420a178447f4847c26495ff02771779191260df6deab4b9352d|48814f8b49a87ba45bd9ef50effea22b5e6ba01a26a225f272d6ef1baefb549c|48814f8b49a87ba45bd9ef50effea22b5e6ba01a26a225f272d6ef1baefb549c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In Stara Zagora, the Neolithic Dwellings Museum shelters two houses of the 6th millennium BC, the best-preserved of their period in Europe, with kitchens, fireplaces and hand grain mills."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Neolithic Dwellings Museum is in Stara Zagora [S1]; it shelters two houses [S1, S2]; the houses date to the 6th millennium BC [S2]; they are the best-preserved dwellings of their period in Europe [S4]; kitchens are found there [S5]; fireplaces are found there [S5]; hand grain mills are found there [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-045 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Neolithic Dwellings Museum is a museum [SUPPORTED: https://en.wikipedia.org/wiki/Neolithic_Dwellings_Museum]; The museum is in Stara Zagora [SUPPORTED: https://en.wikipedia.org/wiki/Neolithic_Dwellings_Museum]; The museum is built around (shelters) two Neolithic houses [SUPPORTED: https://en.wikipedia.org/wiki/Neolithic_Dwellings_Museum]; The two houses date to the 6th millennium BC [SUPPORTED: https://en.wikipedia.org/wiki/Neolithic_Dwellings_Museum]; The dwellings are the best-preserved in Europe from their period [SUPPORTED: https://en.wikipedia.org/wiki/Neolithic_Dwellings_Museum]; The houses'' inventory includes kitchens [SUPPORTED: https://en.wikipedia.org/wiki/Neolithic_Dwellings_Museum]; The houses'' inventory includes fireplaces [SUPPORTED: https://en.wikipedia.org/wiki/Neolithic_Dwellings_Museum]; The houses'' inventory includes hand grain mills [SUPPORTED: https://en.wikipedia.org/wiki/Neolithic_Dwellings_Museum]"}]'::jsonb),
    ('8019f2d1-7e7d-4651-bc79-226f3f7458b0'::uuid, 'card_description', 'An Iron Age triangular earthwork with coursed stone ramparts. Its name comes from the medieval Monceaux family, though the fortification predates them by over two millennia.', 'North west of Dulverton, the Iron Age earthwork of Mounsey Castle forms an irregular triangle of 1.75 hectares, ringed by the remains of a stone rampart between 1.5 metres and 2 metres high.', 'teaser-card-s009:8019f2d1-7e7d-4651-bc79-226f3f7458b0:card_description', 'teaser-card-s009 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '21d96d51295674e0eac13a2cc7700806403f286f713d836e1b9cc01574d6e3b8|75e40a8c1e6b52109a5181a124ee412a0d723d478057472ebd74fc297c790a8a|75e40a8c1e6b52109a5181a124ee412a0d723d478057472ebd74fc297c790a8a', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "North west of Dulverton, the Iron Age earthwork of Mounsey Castle forms an irregular triangle of 1.75 hectares, ringed by the remains of a stone rampart between 1.5 metres and 2 metres high."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies north west of Dulverton [S1]; Mounsey Castle is an Iron Age earthwork [S1]; it forms an irregular triangle [S1]; it covers 1.75 hectares [S1]; it is ringed by the remains of a stone rampart [S3]; the rampart is between 1.5 metres and 2 metres high [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-045 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Mounsey Castle is an earthwork (a hillfort) [SUPPORTED: https://en.wikipedia.org/wiki/Mounsey_Castle]; Mounsey Castle is Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Mounsey_Castle]; It lies north west of Dulverton [SUPPORTED: https://en.wikipedia.org/wiki/Mounsey_Castle]; The earthwork forms an irregular triangle [SUPPORTED: https://en.wikipedia.org/wiki/Mounsey_Castle]; The earthwork measures 1.75 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Mounsey_Castle]; The earthwork is ringed by the remains of a stone rampart [SUPPORTED: https://en.wikipedia.org/wiki/Mounsey_Castle]; The rampart remains are between 1.5 metres and 2 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Mounsey_Castle]"}]'::jsonb),
    ('80fa4dec-a12f-4604-b92e-bfa32b2e0ef6'::uuid, 'card_description', 'Wari-period archaeological zone in the Huamanga Province of Ayacucho. The site sits within the heartland of the Wari state, which dominated Andean civilization 600–1000 AD.', 'Its Quechua name means muddy step or muddy bank: Qunchupata, an archaeological zone in Huamanga, Ayacucho Region, declared a National Cultural Heritage of Peru on December 15, 1998.', 'teaser-card-s009:80fa4dec-a12f-4604-b92e-bfa32b2e0ef6:card_description', 'teaser-card-s009 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '720293a41fc0b99fa01f1c22f882c04ecd18640d1ce15e90c7821680b18a09c2|4bda91c1d28995d65969e70cd2f28a513609745a8a6eb250ac1d1209861c6611|4bda91c1d28995d65969e70cd2f28a513609745a8a6eb250ac1d1209861c6611', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Its Quechua name means muddy step or muddy bank: Qunchupata, an archaeological zone in Huamanga, Ayacucho Region, declared a National Cultural Heritage of Peru on December 15, 1998."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site''s Quechua name means muddy step or muddy bank [S1]; the site is called Qunchupata [S1]; it is an archaeological zone [S1]; it lies in Huamanga (Province) [S2]; it lies in the Ayacucho Region [S2]; it was declared a National Cultural Heritage of Peru [S3]; the declaration was made on December 15, 1998 [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Qunchupata is an archaeological zone (the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Qunchupata,_Ayacucho]; It is in Peru, in the Ayacucho Region [SUPPORTED: https://en.wikipedia.org/wiki/Qunchupata,_Ayacucho]; It is in Huamanga (Huamanga Province) [SUPPORTED: https://en.wikipedia.org/wiki/Qunchupata,_Ayacucho]; The name is Quechua and means muddy step [SUPPORTED: https://en.wikipedia.org/wiki/Qunchupata,_Ayacucho]; The name also means muddy bank (pata: bank of a river) [SUPPORTED: https://en.wikipedia.org/wiki/Qunchupata,_Ayacucho]; The site was declared a National Cultural Heritage of Peru [SUPPORTED: https://en.wikipedia.org/wiki/Qunchupata,_Ayacucho]; The declaration date was December 15, 1998 [SUPPORTED: https://en.wikipedia.org/wiki/Qunchupata,_Ayacucho]"}]'::jsonb),
    ('81ee931d-9549-4cdb-a508-d06ae8971ba4'::uuid, 'card_description', 'The Milseburg is most notable for having been the site of an important Celtic oppidum.', 'An extinct volcano east of Fulda, the Milseburg once held a Celtic oppidum: a stone wall 1,300 metres long girded three sides of its base, and only one of three gates let wagons pass.', 'teaser-card-s009:81ee931d-9549-4cdb-a508-d06ae8971ba4:card_description', 'teaser-card-s009 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '3978339120a569a843412a3155e1c6520ca6af1cc1d60c043135a383dd258cdf|c8ba7c172ff8ee4a0b2d1142f7dc243ed09b3044843e19f30f9ba525f8511e3c|c8ba7c172ff8ee4a0b2d1142f7dc243ed09b3044843e19f30f9ba525f8511e3c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "An extinct volcano east of Fulda, the Milseburg once held a Celtic oppidum: a stone wall 1,300 metres long girded three sides of its base, and only one of three gates let wagons pass."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Milseburg is an extinct volcano [S1]; it lies east of Fulda [S2]; it was the site of a Celtic oppidum [S3]; the fortification included a stone wall [S7]; the wall was 1,300 metres long [S7]; the wall surrounded three sides (north, east, south) of the hill at its base [S7]; the fortification had three gates [S6]; only one of the three gates was passable by wagons [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Milseburg once held a Celtic oppidum (central claim: a Celtic hillfort settlement) [SUPPORTED: https://en.wikipedia.org/wiki/Milseburg]; The oppidum belonged to the past (occupied from about 450 BC to about the turn of the eras) [SUPPORTED: https://en.wikipedia.org/wiki/Milseburg]; The Milseburg is an extinct volcano [SUPPORTED: https://en.wikipedia.org/wiki/Milseburg]; The Milseburg lies east of Fulda [SUPPORTED: https://en.wikipedia.org/wiki/Milseburg]; The main fortification was a stone wall [SUPPORTED: https://en.wikipedia.org/wiki/Milseburg]; The stone wall was 1,300 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Milseburg]; The wall surrounded three sides of the hill (north, east and south) [SUPPORTED: https://en.wikipedia.org/wiki/Milseburg]; The wall ran at the base of the hill [SUPPORTED: https://en.wikipedia.org/wiki/Milseburg]; The oppidum had three gates [SUPPORTED: https://en.wikipedia.org/wiki/Milseburg]; Only one of the three gates was passable by wagons [SUPPORTED: https://en.wikipedia.org/wiki/Milseburg]"}]'::jsonb),
    ('820ff35d-d611-4865-b4e3-27e09843aa9a'::uuid, 'card_description', 'Banoštor is located on the edge of the Fruška Gora Mountain Range and on the Danube River.', 'On the Danube at the edge of Fruška Gora, Celtic Malata became Roman Bononia at Banoštor, a military stronghold of the Cohors Alpinorum, with altars to Jupiter and Neptune nearby.', 'teaser-card-s009:820ff35d-d611-4865-b4e3-27e09843aa9a:card_description', 'teaser-card-s009 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '13b8a9a6984b9641d2c82a440f6bec0831b8b0493c1da64140e030a172b54adb|88283a00aa65bc9fb87a6096e5d0a0a087b1e9cf89775fa19a39bbce378c6c35|88283a00aa65bc9fb87a6096e5d0a0a087b1e9cf89775fa19a39bbce378c6c35', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the Danube at the edge of Fruška Gora, Celtic Malata became Roman Bononia at Banoštor, a military stronghold of the Cohors Alpinorum, with altars to Jupiter and Neptune nearby."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Banoštor lies on the Danube [S6]; it lies at the edge of the Fruška Gora range [S6]; the Celtic settlement at Banoštor was called Malata [S1]; it became Roman Bononia (conquered by the Romans and renamed) [S2]; the Romans made it a military stronghold [S3]; the Cohors Alpinorum, a Roman military unit, was based there [S3]; two altars stood near Bononia, one to Jupiter and one to Neptune [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Banoštor was a Roman military stronghold (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Bano%C5%A1tor]; Banoštor lies on the Danube [SUPPORTED: https://en.wikipedia.org/wiki/Bano%C5%A1tor]; Banoštor lies at the edge of Fruška Gora [SUPPORTED: https://en.wikipedia.org/wiki/Bano%C5%A1tor]; The Celtic settlement at Banoštor was called Malata [SUPPORTED: https://en.wikipedia.org/wiki/Bano%C5%A1tor]; Malata became Roman Bononia after Roman conquest [SUPPORTED: https://en.wikipedia.org/wiki/Bano%C5%A1tor]; The military unit stationed there was the Cohors Alpinorum [SUPPORTED: https://en.wikipedia.org/wiki/Bano%C5%A1tor]; There was an altar to Jupiter near Bononia [SUPPORTED: https://en.wikipedia.org/wiki/Bano%C5%A1tor]; There was an altar to Neptune near Bononia [SUPPORTED: https://en.wikipedia.org/wiki/Bano%C5%A1tor]"}]'::jsonb),
    ('8230ee02-ce60-4b34-b0cd-3beca70274fb'::uuid, 'card_description', 'The Dolni Glavanak Cromlech is an oval stone circle located 2 kilometres west of village of Dolni Glavanak, some 12 kilometres from town of Madzharovo.', 'On a low ridge above the Arda river, the Dolni Glavanak Cromlech is an oval of rough-shaped volcanic blocks from the Early Iron Age: nine still stand, three have fallen.', 'teaser-card-s009:8230ee02-ce60-4b34-b0cd-3beca70274fb:card_description', 'teaser-card-s009 (teaser-card): teaser card, 169 characters, checked PASS, web-verified VERIFIED', 'ecd9be2f8320a1200d7cd68028521251bdda10a8a5563de0cceb2ff76070867c|5428ea4fecd3a5f953074ecd3767f670ae051a058219660d6efddf76d739aa5d|5428ea4fecd3a5f953074ecd3767f670ae051a058219660d6efddf76d739aa5d', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a low ridge above the Arda river, the Dolni Glavanak Cromlech is an oval of rough-shaped volcanic blocks from the Early Iron Age: nine still stand, three have fallen."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site stands on a low ridge [S2]; the ridge is above the Arda river [S2]; the Dolni Glavanak Cromlech is an oval stone circle [S1]; it is made of roughly shaped blocks [S3]; the blocks are of volcanic rock [S3]; the cromlech dates from the Early Iron Age [S7]; nine blocks still stand [S4]; three blocks have fallen [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Dolni Glavanak Cromlech is a stone circle (cromlech) in Bulgaria (central claim: a stone circle monument) [SUPPORTED: https://en.wikipedia.org/wiki/Dolni_Glavanak_Cromlech]; The circle is oval [SUPPORTED: https://en.wikipedia.org/wiki/Dolni_Glavanak_Cromlech]; It stands on a low ridge [SUPPORTED: https://en.wikipedia.org/wiki/Dolni_Glavanak_Cromlech]; The ridge is above the Arda river [SUPPORTED: https://en.wikipedia.org/wiki/Dolni_Glavanak_Cromlech]; The blocks are roughly shaped [SUPPORTED: https://en.wikipedia.org/wiki/Dolni_Glavanak_Cromlech]; The blocks are of volcanic rock [SUPPORTED: https://en.wikipedia.org/wiki/Dolni_Glavanak_Cromlech]; It dates to the Early Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Dolni_Glavanak_Cromlech]; Nine blocks still stand [SUPPORTED: https://en.wikipedia.org/wiki/Dolni_Glavanak_Cromlech]; Three blocks have fallen [SUPPORTED: https://en.wikipedia.org/wiki/Dolni_Glavanak_Cromlech]"}]'::jsonb),
    ('82e28821-420e-426b-a72f-cbbb27fa64a3'::uuid, 'card_description', 'Ruins of a 150 AD Roman temple dedicated to Apollo. Only the foundation and scattered column drums remain — but they hint at a structure of massive scale.', 'On the Mediterranean coast at Side, five columns of Apollon Tapınağı have stood side by side over centuries, a Roman temple to the god of music, harmony and light built around 150 A.D.', 'teaser-card-s009:82e28821-420e-426b-a72f-cbbb27fa64a3:card_description', 'teaser-card-s009 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '3888ff24ee0f35f702e4ee7f84c1996902ae4ca13ff83d403abd17f84ae7a4e5|3acb4d9af0b90377e3d868bbfb1a88503ef5c9fe45c03bd589bbc696f55052ec|3acb4d9af0b90377e3d868bbfb1a88503ef5c9fe45c03bd589bbc696f55052ec', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the Mediterranean coast at Side, five columns of Apollon Tapınağı have stood side by side over centuries, a Roman temple to the god of music, harmony and light built around 150 A.D."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the temple is on the Mediterranean coast [S1]; it is at Side [S1]; five columns of it exist [S3]; the five columns have stood side by side over centuries [S3]; it is a Roman temple [S1]; it is dedicated to the god of music, harmony and light (Apollo) [S1]; it was built around 150 A.D. [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Temple of Apollo (Apollon Tapınağı) is a Roman temple (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Side)]; It was built around 150 A.D. [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Side)]; It is at Side [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Side)]; Side lies on the Mediterranean coast [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Side)]; The temple was dedicated to Apollo [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Side)]; Apollo is the god of music, harmony and light [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Side)]; Five columns of the temple remain [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Side)]; The columns stood side by side [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Side)]; They stood over centuries [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Side)]"}]'::jsonb),
    ('82f2d8e5-e3fa-4782-b580-a7eca3ecad45'::uuid, 'card_description', NULL, 'Around 90 AD the Main Limes made the River Main itself a Roman frontier for about 50 kilometres. Of the many watchtowers that probably stood along it, only one has been identified to date.', 'teaser-card-s009:82f2d8e5-e3fa-4782-b580-a7eca3ecad45:card_description', 'teaser-card-s009 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '2df131da7e5a983d4dec6d09c5084ed1bed43c27f96fd8fd2c7128e042a76862|5147de58725b19962fdb949e61aafe55c7471acbf452962ac9459221760f8dc7|5147de58725b19962fdb949e61aafe55c7471acbf452962ac9459221760f8dc7', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Around 90 AD the Main Limes made the River Main itself a Roman frontier for about 50 kilometres. Of the many watchtowers that probably stood along it, only one has been identified to date."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Main Limes dates to around 90 AD [S1]; it formed a frontier of the Roman Empire [S1]; the River Main itself served as the boundary along it [S1, S2]; the river forms a natural boundary for about 50 kilometres [S2]; many watchtowers probably stood along the Main [S3]; only one watchtower has been identified to date (the others are not identified) [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-047 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Main Limes is a Roman frontier (limes), a section of the Upper Germanic-Rhaetian Limes [SUPPORTED: https://en.wikipedia.org/wiki/Main_Limes]; The Main Limes is in Germany [SUPPORTED: https://en.wikipedia.org/wiki/Main_Limes]; The Main Limes was built around 90 AD [SUPPORTED: https://en.wikipedia.org/wiki/Main_Limes]; The River Main itself served as the Roman frontier (natural boundary) in this section [SUPPORTED: https://en.wikipedia.org/wiki/Main_Limes]; The stretch where the Main was the frontier is about 50 kilometres long [SUPPORTED: https://en.wikipedia.org/wiki/Main_Limes]; Many watchtowers probably stood along the Main [SUPPORTED: https://en.wikipedia.org/wiki/Main_Limes]; Only one watchtower along the Main Limes has been identified to date [SUPPORTED: https://en.wikipedia.org/wiki/Main_Limes]"}]'::jsonb),
    ('833d2de9-5bc4-425d-b5a5-111d742c8f0d'::uuid, 'card_description', 'A 345-metre-long cave with Paleolithic deposits and a narrow, high entrance 40 metres above the river. It served as both a prehistoric shelter and a later hiding place for rebels.', 'Hadži-Prodan''s Cave held only fifteen Palaeolithic artifacts, yet it and nearby Šalitrena Cave are so far the only Central Balkan caves with traces of Gravettian or Epigravettian people.', 'teaser-card-s009:833d2de9-5bc4-425d-b5a5-111d742c8f0d:card_description', 'teaser-card-s009 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '41269c591cfaad1fac5c0916a3ce488cc753b3b4f80b6253580dd726a7590be3|a474d2692ec8ae2c758c405391303cdd734540ce82237fab1e493b5071d9eb12|a474d2692ec8ae2c758c405391303cdd734540ce82237fab1e493b5071d9eb12', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Hadži-Prodan''s Cave held only fifteen Palaeolithic artifacts, yet it and nearby Šalitrena Cave are so far the only Central Balkan caves with traces of Gravettian or Epigravettian people."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "only fifteen Palaeolithic artifacts were found in Hadži-Prodan''s Cave [S5]; Šalitrena Cave is nearby [S6]; the two caves are so far the only cave sites in the Central Balkan mountains with evidence of Gravettian and/or Epigravettian human presence [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-047 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Hadži-Prodan''s Cave is a cave, a Palaeolithic archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Had%C5%BEi-Prodan%27s_Cave]; The cave is in Serbia (near Ivanjica) [SUPPORTED: https://en.wikipedia.org/wiki/Had%C5%BEi-Prodan%27s_Cave]; Only fifteen Palaeolithic artifacts were found inside the cave [SUPPORTED: https://en.wikipedia.org/wiki/Had%C5%BEi-Prodan%27s_Cave]; Šalitrena Cave is nearby Hadži-Prodan''s Cave [SUPPORTED: https://en.wikipedia.org/wiki/Had%C5%BEi-Prodan%27s_Cave]; Hadži-Prodan''s Cave and Šalitrena Cave are so far the only cave sites in the Central Balkans (mountains) with evidence of human presence in a Gravettian and/or Epigravettian context [SUPPORTED: https://en.wikipedia.org/wiki/Had%C5%BEi-Prodan%27s_Cave]"}]'::jsonb),
    ('83893760-fcb6-4824-8ee9-7e1c6fc74852'::uuid, 'card_description', 'Dead Woman''s Ditch is an earthwork which has been scheduled as an ancient monument in Over Stowey, Somerset.', 'Across the Quantock Hills runs Dead Woman''s Ditch, a 1 kilometre long earthwork presumed prehistoric and of unknown purpose, now cut through by tracks and a road and badly eroded in places.', 'teaser-card-s009:83893760-fcb6-4824-8ee9-7e1c6fc74852:card_description', 'teaser-card-s009 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '4864634c37cd9b5c3a4d0dd0584e5315bc6d77421b6f268252fa4568acffef46|47ff0213970734974010bb8fdd80157f3b503c238887e21e03dae28d02cf471f|47ff0213970734974010bb8fdd80157f3b503c238887e21e03dae28d02cf471f', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Across the Quantock Hills runs Dead Woman''s Ditch, a 1 kilometre long earthwork presumed prehistoric and of unknown purpose, now cut through by tracks and a road and badly eroded in places."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Dead Woman''s Ditch lies in/on the Quantock Hills [S1]; it is an earthwork [S1]; it is 1 kilometre long [S3]; it is presumed to be prehistoric [S2]; its purpose is unknown [S2]; it has been cut through by tracks and a road [S3]; it is badly eroded in places [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-047 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Dead Woman''s Ditch is an earthwork [SUPPORTED: https://en.wikipedia.org/wiki/Dead_Woman%27s_Ditch]; It lies on the Quantock Hills [SUPPORTED: https://en.wikipedia.org/wiki/Dead_Woman%27s_Ditch]; It lies in England (Over Stowey, Somerset) [SUPPORTED: https://en.wikipedia.org/wiki/Dead_Woman%27s_Ditch]; The earthwork is 1 kilometre long [SUPPORTED: https://en.wikipedia.org/wiki/Dead_Woman%27s_Ditch]; The earthwork is presumed to be prehistoric [SUPPORTED: https://en.wikipedia.org/wiki/Dead_Woman%27s_Ditch]; The earthwork''s purpose is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Dead_Woman%27s_Ditch]; The earthwork is cut through by tracks and a road [SUPPORTED: https://en.wikipedia.org/wiki/Dead_Woman%27s_Ditch]; The earthwork is badly eroded in places [SUPPORTED: https://en.wikipedia.org/wiki/Dead_Woman%27s_Ditch]"}]'::jsonb),
    ('838d58ef-f389-42b1-8740-198904bf1cc1'::uuid, 'card_description', '2nd century BC–3rd century AD hill fort in Maharashtra with temples to Lord Shiva and the patron goddess Bhoraidevi. Sudha Gad fuses military and sacred purpose — fortress and shrine on one summit.', '620 metres up, the summit plateau of Sudha Gad Fort holds two lakes, a big granary, tombs, a shrine and scattered ruins. Its origin is said to date back to the 2nd century B.C.', 'teaser-card-s009:838d58ef-f389-42b1-8740-198904bf1cc1:card_description', 'teaser-card-s009 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '61f4045a17e584367a0336e49ad9a8572fa3597cf60ecc95940b1a0965f9965b|61893f609db8e2d53150b17299ca81bed20a062a73a9d7af6f158e01e16cc31c|61893f609db8e2d53150b17299ca81bed20a062a73a9d7af6f158e01e16cc31c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "620 metres up, the summit plateau of Sudha Gad Fort holds two lakes, a big granary, tombs, a shrine and scattered ruins. Its origin is said to date back to the 2nd century B.C."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the summit is 620 metres above sea level [S3]; the fort has a plateau at its summit [S8]; the plateau holds two lakes [S8]; the plateau holds a big granary [S8]; the plateau holds tombs [S8]; the plateau holds a shrine [S8]; the plateau holds scattered ruins [S8]; the fort''s origin is said to date back to the 2nd century B.C. [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-047 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Sudha Gad (Sudhagad) is a hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Sudhagad]; 