    ('8a3a0f0e-6656-4b50-92ff-7f02f9f1548e'::uuid, 'card_description', 'The grave is structurally untouched since ancient times, but may have been cleared then.', 'On the island of Møn, a 7.5 m passage leads into the 10 m chamber of Kong Asgers Høj, a Neolithic passage grave. In 1839 a merchant came seeking treasure and found it empty.', 'teaser-card-s009:8a3a0f0e-6656-4b50-92ff-7f02f9f1548e:card_description', 'teaser-card-s009 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', 'af37b17dbbdd0e69fe997a7c92d35d1591221a2f8018643ed6fdbc7bcfd0b6f9|af08302d06ab925f8493c4377cdf443adb4e4731f1a7688de7f99fda1c50bb69|af08302d06ab925f8493c4377cdf443adb4e4731f1a7688de7f99fda1c50bb69', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the island of Møn, a 7.5 m passage leads into the 10 m chamber of Kong Asgers Høj, a Neolithic passage grave. In 1839 a merchant came seeking treasure and found it empty."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Kong Asgers Hoj is on the island of Mon [S1]; a passage of 7.5 m leads into the chamber [S3]; the chamber is 10 m long [S3]; it is a Neolithic passage grave [S1, S2]; in 1839 a merchant came seeking treasure [S4]; he found the grave empty [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Kong Asgers Høj is a passage grave on the island of Møn (Denmark) [SUPPORTED: https://en.wikipedia.org/wiki/Kong_Asgers_H%C3%B8j]; It is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Kong_Asgers_H%C3%B8j]; The passage is 7.5 m long [SUPPORTED: https://en.wikipedia.org/wiki/Kong_Asgers_H%C3%B8j]; The chamber is 10 m long [SUPPORTED: https://en.wikipedia.org/wiki/Kong_Asgers_H%C3%B8j]; In 1839 a merchant came seeking treasure [SUPPORTED: https://en.wikipedia.org/wiki/Kong_Asgers_H%C3%B8j]; The merchant found the grave empty [SUPPORTED: https://en.wikipedia.org/wiki/Kong_Asgers_H%C3%B8j]"}]'::jsonb),
    ('8a4ea255-abed-47fe-9c37-636756e90450'::uuid, 'card_description', 'Amphipolis was originally a colony of ancient Athens and was the site of the battle between the Spartans and Athenians in 422 BC.', 'Walls 7.5 km long once ringed Amphipolis, the Athenian colony where Spartans and Athenians fought in 422 BC and Alexander the Great prepared the campaigns that led him into Asia.', 'teaser-card-s009:8a4ea255-abed-47fe-9c37-636756e90450:card_description', 'teaser-card-s009 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '143357ae860c998545acfb6b9a101280726ab1663d1cafd117cb561d59b375e5|97d3d8a398e03b0af12476f6023ed0c2d9105f4b75ebf5ca737879528e019a55|97d3d8a398e03b0af12476f6023ed0c2d9105f4b75ebf5ca737879528e019a55', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Walls 7.5 km long once ringed Amphipolis, the Athenian colony where Spartans and Athenians fought in 422 BC and Alexander the Great prepared the campaigns that led him into Asia."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Amphipolis had walls 7.5 km long [S7]; the walls once ringed (enclosed) the city [S7]; Amphipolis was an Athenian colony [S2]; Spartans and Athenians fought a battle there in 422 BC [S2]; Alexander the Great prepared campaigns there that led him into Asia [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Amphipolis was an ancient Greek city (polis), in Greece [SUPPORTED: https://en.wikipedia.org/wiki/Amphipolis]; Amphipolis had walls 7.5 km long [SUPPORTED: https://en.wikipedia.org/wiki/Amphipolis]; The walls ringed the city (a fortified perimeter around the ancient town) [SUPPORTED: https://en.wikipedia.org/wiki/Amphipolis]; Amphipolis was an Athenian colony [SUPPORTED: https://en.wikipedia.org/wiki/Amphipolis]; Spartans and Athenians fought at Amphipolis in 422 BC [SUPPORTED: https://en.wikipedia.org/wiki/Amphipolis]; Alexander the Great prepared at Amphipolis the campaigns that led him into Asia [SUPPORTED: https://en.wikipedia.org/wiki/Amphipolis]"}]'::jsonb),
    ('8ad7daf1-1126-4f0a-997f-84dd82d4c396'::uuid, 'card_description', 'The thermal complex was built in the middle of the 2nd century AD, and continued to be populated until the 4th century AD.', 'At Ad Quintum, the two branches of the Via Egnatia met at a Roman way station with a thermal complex, built in the middle of the 2nd century AD and populated until the 4th century AD.', 'teaser-card-s009:8ad7daf1-1126-4f0a-997f-84dd82d4c396:card_description', 'teaser-card-s009 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '42e6d9f7f89f44867b46f418eb99d34e85bd84b7396887592cda155a2e050e92|8451bfd9d21d45bc83967898dffdbbe6086e10821b4a4708f3c120d65aa49116|8451bfd9d21d45bc83967898dffdbbe6086e10821b4a4708f3c120d65aa49116', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At Ad Quintum, the two branches of the Via Egnatia met at a Roman way station with a thermal complex, built in the middle of the 2nd century AD and populated until the 4th century AD."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the two branches of the Via Egnatia met at Ad Quintum [S3]; Ad Quintum was a way station [S2]; the station was Roman [S1, S2]; it had a thermal complex [S1]; the thermal complex was built in the middle of the 2nd century AD [S4]; it was populated until the 4th century AD [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Ad Quintum was a Roman settlement with a thermal complex [SUPPORTED: https://en.wikipedia.org/wiki/Ad_Quintum]; Ad Quintum was a way station (mutatio) [SUPPORTED: https://en.wikipedia.org/wiki/Ad_Quintum]; The way station lay on the Via Egnatia [SUPPORTED: https://en.wikipedia.org/wiki/Ad_Quintum]; The two branches of the Via Egnatia met at Ad Quintum [SUPPORTED: https://en.wikipedia.org/wiki/Ad_Quintum]; Ad Quintum had a thermal complex [SUPPORTED: https://en.wikipedia.org/wiki/Ad_Quintum]; The thermal complex was built in the middle of the 2nd century AD [SUPPORTED: https://en.wikipedia.org/wiki/Ad_Quintum]; It was populated until the 4th century AD [SUPPORTED: https://en.wikipedia.org/wiki/Ad_Quintum]"}]'::jsonb),
    ('8c44a3a9-c945-44e8-8dc2-1baab82890ea'::uuid, 'card_description', 'In 2022, excavations led to the discovery of the archaic temple of Athena on the acropolis of Velia.', 'On the Tyrrhenian coast, Greeks from Phocaea founded Velia as Hyele around 538–535 BCE, home of Parmenides and Zeno. In 2022, digs found the archaic temple of Athena on its acropolis.', 'teaser-card-s009:8c44a3a9-c945-44e8-8dc2-1baab82890ea:card_description', 'teaser-card-s009 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '655e6579e3e1ed340c6b3fdea4d9235853aa69f4199e0dd4eb6824a51aa82144|80aa4eb603a0ca1e8e6ce3d1d2ffce8e32e8417515e94b24a6a802b7edb149de|80aa4eb603a0ca1e8e6ce3d1d2ffce8e32e8417515e94b24a6a802b7edb149de', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the Tyrrhenian coast, Greeks from Phocaea founded Velia as Hyele around 538–535 BCE, home of Parmenides and Zeno. In 2022, digs found the archaic temple of Athena on its acropolis."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Velia is on the Tyrrhenian coast [S1]; Greeks from Phocaea founded it [S3]; it was founded as Hyele [S3]; the founding was around 538-535 BCE [S3]; it was the home of Parmenides and Zeno [S4]; in 2022 excavations found the archaic temple of Athena [S6]; the temple is on the acropolis of Velia [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Velia is an ancient city (a settlement) in Italy [SUPPORTED: https://en.wikipedia.org/wiki/Velia]; Velia lies on the Tyrrhenian coast [SUPPORTED: https://en.wikipedia.org/wiki/Velia]; Greeks from Phocaea founded Velia [SUPPORTED: https://en.wikipedia.org/wiki/Velia]; The city was founded under the name Hyele [SUPPORTED: https://en.wikipedia.org/wiki/Velia]; The foundation date was around 538-535 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Velia]; Velia was the home of Parmenides [SUPPORTED: https://en.wikipedia.org/wiki/Velia]; Velia was the home of Zeno [SUPPORTED: https://en.wikipedia.org/wiki/Velia]; In 2022, excavations found the archaic temple of Athena [SUPPORTED: https://en.wikipedia.org/wiki/Velia]; The archaic temple of Athena lies on the acropolis of Velia [SUPPORTED: https://en.wikipedia.org/wiki/Velia]"}]'::jsonb),
    ('8d114f26-1360-4e96-a34a-cbe4415edb71'::uuid, 'card_description', 'An Inca royal estate at 3,650 metres overlooking the Sacred Valley. Known as "Little Cuzco," it was built by Emperor Viracocha around 1420 AD.', 'Overlooking the Sacred Valley from 3,650 meters, Huchuy Qosqo, Quechua for Little Cuzco, keeps a great hall 40 m long, and water arrives by an Inca channel lined with stones.', 'teaser-card-s009:8d114f26-1360-4e96-a34a-cbe4415edb71:card_description', 'teaser-card-s009 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', 'fcb1256e14120e7d54ec3f6185cfd7ec53e13f4cbcffa57b75e54450bfa7899b|1f27affef84eec8d5de10fc08ed07e2cc403c66223c4da30a09f6d1813e44fe5|1f27affef84eec8d5de10fc08ed07e2cc403c66223c4da30a09f6d1813e44fe5', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Overlooking the Sacred Valley from 3,650 meters, Huchuy Qosqo, Quechua for Little Cuzco, keeps a great hall 40 m long, and water arrives by an Inca channel lined with stones."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Huchuy Qosqo overlooks the Sacred Valley [S3]; it lies at 3,650 meters [S3]; the name is Quechua for Little Cuzco [S2]; it has a great hall 40 m long [S6]; water reaches the site by an Inca-built channel [S7]; the channel is lined with stones [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Huchuy Qosqo is an Inca archaeological site in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Huchuy_Qosqo]; The site overlooks the Sacred Valley [SUPPORTED: https://en.wikipedia.org/wiki/Huchuy_Qosqo]; The site lies at 3,650 meters elevation [SUPPORTED: https://en.wikipedia.org/wiki/Huchuy_Qosqo]; Huchuy Qosqo is Quechua for Little Cuzco [SUPPORTED: https://en.wikipedia.org/wiki/Huchuy_Qosqo]; The site has a great hall (kallanka) 40 m long [SUPPORTED: https://en.wikipedia.org/wiki/Huchuy_Qosqo]; Water is provided to the site by an Inca-built channel [SUPPORTED: https://en.wikipedia.org/wiki/Huchuy_Qosqo]; The Inca channel is lined with stones [SUPPORTED: https://en.wikipedia.org/wiki/Huchuy_Qosqo]"}]'::jsonb),
    ('8d8753ae-9935-4ffb-b578-de5907999f68'::uuid, 'card_description', 'The Sanctuary of Athena Nike was demolished by the Persians in 480-479 BC and a temple was built over the remains. The Temple of Athena Nike, the smallest on the Acropolis, was finished around 420 BC.', 'On a steep bastion right of the Propylaea stands the Temple of Athena Nike, the smallest temple on the Acropolis and its earliest fully Ionic one, finished around 420 BC.', 'teaser-card-s009:8d8753ae-9935-4ffb-b578-de5907999f68:card_description', 'teaser-card-s009 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', '7eee1418d197581c3a2785fdf2a19f7a5f818ff499170d30bfb9cb42261395f0|856fe7e4f114678ee5ad58c4f55309171a0914eef4880e21f6f4c9e5f2e1323f|856fe7e4f114678ee5ad58c4f55309171a0914eef4880e21f6f4c9e5f2e1323f', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a steep bastion right of the Propylaea stands the Temple of Athena Nike, the smallest temple on the Acropolis and its earliest fully Ionic one, finished around 420 BC."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the temple stands on a steep bastion [S3]; it stands to the right of the Propylaea [S3]; it is the smallest temple on the Acropolis [S1, S6]; it is the earliest fully Ionic temple on the Acropolis [S2]; it was finished around 420 BC [S5, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Temple of Athena Nike is a temple on the Acropolis of Athens, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_Nike]; It stands on a steep bastion [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_Nike]; It stands to the right of the Propylaea [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_Nike]; It is the smallest temple on the Acropolis [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_Nike]; It is the earliest of the fully Ionic temples on the Acropolis (earliest) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_Nike]; It is a fully Ionic temple on the Acropolis [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_Nike]; It was finished around 420 BC [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_Nike]"}]'::jsonb),
    ('8de309a1-1291-4878-8f63-694b2276b934'::uuid, 'card_description', 'As the Western Roman Empire declined during the 4th century, by which time Christianity had become the official religion, the theatre was closed by official edict in AD 391.', 'The grand facade of the Roman Theatre of Orange measures 103 meters long and 37 meters high. A wooden roof once sheltered its audience, until a fire destroyed it, as the walls still show.', 'teaser-card-s009:8de309a1-1291-4878-8f63-694b2276b934:card_description', 'teaser-card-s009 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'dc42336c4bcd8bae5a470a4a19618db818e561b03aa3e42c7610b7fda5a2e069|7583ecb9d474cd5e6280f10456aaa1d89245d0d50be9bbd3ed2762b9b9f4186a|7583ecb9d474cd5e6280f10456aaa1d89245d0d50be9bbd3ed2762b9b9f4186a', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The grand facade of the Roman Theatre of Orange measures 103 meters long and 37 meters high. A wooden roof once sheltered its audience, until a fire destroyed it, as the walls still show."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the facade is grand [S4]; the facade measures 103 meters long [S4]; the facade measures 37 meters high [S4]; a wooden roof once sheltered the audience [S5]; a fire destroyed the roof [S6]; the walls show evidence of the fire [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Roman Theatre of Orange is a Roman theatre in Orange, France [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_of_Orange]; The theatre has a grand facade [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_of_Orange]; The facade measures 103 meters long [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_of_Orange]; The facade measures 37 meters high [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_of_Orange]; A wooden roof once sheltered the audience [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_of_Orange]; The roof was destroyed by a fire [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_of_Orange]; The walls still show evidence of the fire [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_of_Orange]"}]'::jsonb),
    ('8de612f7-9569-4b28-9883-3143d47fb309'::uuid, 'card_description', 'Roman-era port at the confluence of the Sar and Ulla rivers, seat of the Celtic Capori tribe. Refounded as Iria Flavia on the Via Nova road — later a key early Christian episcopal centre.', 'Where the Sar meets the Ulla, the port of Iria was the main seat of the Celtic Capori tribe. The Romans refounded it as Iria Flavia to compliment the emperor Vespasian.', 'teaser-card-s009:8de612f7-9569-4b28-9883-3143d47fb309:card_description', 'teaser-card-s009 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', 'e25064f0c48e80aa8ef826fb50b087f2e0484e7fb58ff1fdc365814ab7f27772|7759304c970b97e5cdad0fadb5a8f4fbeb59dc5148c736b8b680a5861aeda30a|7759304c970b97e5cdad0fadb5a8f4fbeb59dc5148c736b8b680a5861aeda30a', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Where the Sar meets the Ulla, the port of Iria was the main seat of the Celtic Capori tribe. The Romans refounded it as Iria Flavia to compliment the emperor Vespasian."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Iria lies where the Sar meets the Ulla [S2]; Iria was a port [S2]; it was the main seat of the Celtic Capori tribe [S2]; the Romans refounded it as Iria Flavia [S3]; the name honoured (complimented) the emperor Vespasian [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Iria Flavia is an ancient settlement in Galicia, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Iria_Flavia]; Iria lies where the Sar meets the Ulla [SUPPORTED: https://en.wikipedia.org/wiki/Iria_Flavia]; Iria was a port [SUPPORTED: https://en.wikipedia.org/wiki/Iria_Flavia]; Iria was the main seat of the Celtic Capori tribe [SUPPORTED: https://en.wikipedia.org/wiki/Iria_Flavia]; The Capori were a Celtic tribe [SUPPORTED: https://en.wikipedia.org/wiki/Capori]; The Romans refounded the port as Iria Flavia [SUPPORTED: https://en.wikipedia.org/wiki/Iria_Flavia]; The name Iria Flavia was given to compliment the emperor Vespasian [SUPPORTED: https://en.wikipedia.org/wiki/Iria_Flavia]"}]'::jsonb),
    ('8dec4979-434b-46dd-9468-f829d6d1e713'::uuid, 'card_description', 'A bridge on Roman foundations with a 37.3-metre main span, rebuilt in Gothic style in 1283 and reconstructed again in 1965. A stone chapel sits on top of the arch.', 'A stone chapel crowns the 37.3 metre span of the Pont del Diable over the river Llobregat, and at its eastern abutment a Roman triumphal arch still stands from the days of the Via Augusta.', 'teaser-card-s009:8dec4979-434b-46dd-9468-f829d6d1e713:card_description', 'teaser-card-s009 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '40fe7d1929d2e701a85006b51bba8d7d6688ee3c171cc865f7f4e18b49e4658c|e70ecbe0db9a1d443306f71857f3ac9a0f8428058779ba6a7059243dec4c485c|e70ecbe0db9a1d443306f71857f3ac9a0f8428058779ba6a7059243dec4c485c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "A stone chapel crowns the 37.3 metre span of the Pont del Diable over the river Llobregat, and at its eastern abutment a Roman triumphal arch still stands from the days of the Via Augusta."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "a stone chapel stands on top of the main span of the Pont del Diable [S2]; the main span measures 37.3 metres [S2]; the bridge crosses the river Llobregat [S1]; a Roman triumphal arch stands at the bridge''s eastern abutment [S6]; the arch still stands today [S6]; the arch dates from the Roman days of the Via Augusta, the road the original Roman bridge was part of [S5, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Pont del Diable is a bridge in Catalonia, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Pont_del_Diable]; The bridge crosses the river Llobregat [SUPPORTED: https://en.wikipedia.org/wiki/Pont_del_Diable]; The main span is 37.3 metres [SUPPORTED: https://en.wikipedia.org/wiki/Pont_del_Diable]; A stone chapel sits on top of the main span [SUPPORTED: https://en.wikipedia.org/wiki/Pont_del_Diable]; A Roman triumphal arch is at the bridge''s eastern abutment [SUPPORTED: https://en.wikipedia.org/wiki/Pont_del_Diable]; The triumphal arch still stands today [SUPPORTED: https://en.wikipedia.org/wiki/Pont_del_Diable]; The Roman bridge belonged to the Via Augusta [SUPPORTED: https://en.wikipedia.org/wiki/Pont_del_Diable]"}]'::jsonb),
    ('90bf9ebf-4050-433f-aaef-3b31dd3053d6'::uuid, 'card_description', 'Built 200–400 AD on the Pacific coastal plain, Balberta is the only known Early Classic Maya site there with exposed architecture not buried by later construction.', 'On the Pacific coastal plain, Balberta grew into a Maya power that traded with distant Teotihuacan, peaked between AD 200 and AD 400, and was then suddenly abandoned around AD 400.', 'teaser-card-s009:90bf9ebf-4050-433f-aaef-3b31dd3053d6:card_description', 'teaser-card-s009 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'c7a1ad11f1847de69c8b5a931219eae547dab8fba503e1a04ac34bad7b15229b|db7cf16d66acc7694952fe94482880c8437bb40f2e22c4f3fc4c57909a0a9ad0|db7cf16d66acc7694952fe94482880c8437bb40f2e22c4f3fc4c57909a0a9ad0', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the Pacific coastal plain, Balberta grew into a Maya power that traded with distant Teotihuacan, peaked between AD 200 and AD 400, and was then suddenly abandoned around AD 400."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Balberta lies on the Pacific coastal plain [S1]; Balberta is a Maya site [S1]; Balberta grew into a power [S4, S6]; Balberta traded with distant Teotihuacan [S5]; it peaked between AD 200 and AD 400 [S4]; it was suddenly abandoned around AD 400 [S7]; the abandonment came after the peak [S4, S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Balberta is an archaeological site of the Maya civilization [SUPPORTED: https://en.wikipedia.org/wiki/Balberta]; Balberta lies on the Pacific coastal plain [SUPPORTED: https://en.wikipedia.org/wiki/Balberta]; Balberta is in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Balberta]; Balberta grew into a major power (rapid growth, state-level polity dominating a wide area) [SUPPORTED: https://en.wikipedia.org/wiki/Balberta]; Balberta traded with Teotihuacan [SUPPORTED: https://en.wikipedia.org/wiki/Balberta]; Teotihuacan was distant from Balberta [SUPPORTED: https://en.wikipedia.org/wiki/Balberta]; Balberta peaked between AD 200 and AD 400 [SUPPORTED: https://en.wikipedia.org/wiki/Balberta]; Balberta was suddenly abandoned around AD 400 [SUPPORTED: https://en.wikipedia.org/wiki/Balberta]"}]'::jsonb),
    ('90cfd278-3aac-40b9-9d3c-d50a40bd3051'::uuid, 'card_description', 'A stone circle on Exmoor moorland, part of a Late Neolithic to Early Bronze Age tradition. The purpose of these rings is unknown, though ritual gathering is widely suspected.', 'On Exmoor heathland, the Withypool Stone Circle keeps around thirty small gritstones in a ring about 36.4 metres across, where there may once have been around 100. Gaps open north and west.', 'teaser-card-s009:90cfd278-3aac-40b9-9d3c-d50a40bd3051:card_description', 'teaser-card-s009 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'fab467c5fc7f9607013f206d820264510d6cc36fcc16a19ec4132d9f242b04dd|a2e0f944bec3fa675da3161d930da4c8b17bd0347a2ad8ae0c178bcb62a121fd|a2e0f944bec3fa675da3161d930da4c8b17bd0347a2ad8ae0c178bcb62a121fd', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On Exmoor heathland, the Withypool Stone Circle keeps around thirty small gritstones in a ring about 36.4 metres across, where there may once have been around 100. Gaps open north and west."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Withypool Stone Circle lies on Exmoor [S1]; it lies on heathland [S3]; around thirty small gritstones remain [S5]; the ring is about 36.4 metres across [S4]; there may once have been around 100 stones [S5]; there are gaps on the north and west sides [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Withypool Stone Circle is a stone circle on Exmoor in England [SUPPORTED: https://en.wikipedia.org/wiki/Withypool_Stone_Circle]; The circle lies on Exmoor heathland [SUPPORTED: https://en.wikipedia.org/wiki/Withypool_Stone_Circle]; The ring is about 36.4 metres across [SUPPORTED: https://en.wikipedia.org/wiki/Withypool_Stone_Circle]; Around thirty small gritstones remain [SUPPORTED: https://en.wikipedia.org/wiki/Withypool_Stone_Circle]; There may originally have been around 100 stones [SUPPORTED: https://en.wikipedia.org/wiki/Withypool_Stone_Circle]; There are gaps in the ring on the northern and western sides [SUPPORTED: https://en.wikipedia.org/wiki/Withypool_Stone_Circle]"}]'::jsonb),
    ('90f8d91e-5465-41c2-a297-8f33269c241e'::uuid, 'card_description', 'A Roman theatre at 1,000 m elevation built for the region''s most important city. Its stage wall is carved directly into the hilltop rock.', 'Carved out of rock under Emperor Tiberius, the Theatre of Clunia Sulpicia held 10,000 spectators. In the 2nd century it became an amphitheater; thirty burials were found by its stage house.', 'teaser-card-s009:90f8d91e-5465-41c2-a297-8f33269c241e:card_description', 'teaser-card-s009 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '6b0ab54e360cb2f74383f5b9285197fe62e01f29f3c6e03d9fa57f272515f82b|7ca757c618b49491115186110341b60370b64b58027aa62d5cda6713c455e652|7ca757c618b49491115186110341b60370b64b58027aa62d5cda6713c455e652', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Carved out of rock under Emperor Tiberius, the Theatre of Clunia Sulpicia held 10,000 spectators. In the 2nd century it became an amphitheater; thirty burials were found by its stage house."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the theatre was carved out of rock [S4]; it was built under Emperor Tiberius [S2]; it held 10,000 spectators [S4]; in the 2nd century it was renovated and adapted for use as an amphitheater [S6]; thirty burials were found next to the remains of the postscenium, the rear of the stage building [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Theatre of Clunia Sulpicia is a Roman theatre in the ancient city of Clunia Sulpicia in northern Spain (province of Burgos) [SUPPORTED: https://en.wikipedia.org/wiki/Theatre_of_Clunia_Sulpicia]; The theatre was carved out of rock [SUPPORTED: https://en.wikipedia.org/wiki/Theatre_of_Clunia_Sulpicia]; It was built under Emperor Tiberius [SUPPORTED: https://en.wikipedia.org/wiki/Theatre_of_Clunia_Sulpicia]; The theatre held 10,000 spectators [SUPPORTED: https://en.wikipedia.org/wiki/Theatre_of_Clunia_Sulpicia]; In the 2nd century it was converted into an amphitheater [SUPPORTED: https://en.wikipedia.org/wiki/Theatre_of_Clunia_Sulpicia]; Thirty burials were found by the stage house (postscenium) [SUPPORTED: https://en.wikipedia.org/wiki/Theatre_of_Clunia_Sulpicia]"}]'::jsonb),
    ('9192a16a-acc4-4aea-9d6e-19e74b9d8a38'::uuid, 'card_description', 'Gallo-Roman baths from the 2nd century AD, partially built into a church with the hypocaust heating system preserved beneath the nave.', 'Part of the Romano-Gallic Baths of Entrammes lives on inside a church in Mayenne, and beneath it lies a hypocaust in good condition, proof of 2nd century thermal baths discovered in 1987.', 'teaser-card-s009:9192a16a-acc4-4aea-9d6e-19e74b9d8a38:card_description', 'teaser-card-s009 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '0cd9954824cee2c4484ad6b9dc80df5066d42a01ae6ba216f781815e23176d01|fa7bdd56e30d5206e519e937a6681dc287117eded1ccc833c7d2caa28ec57bc3|fa7bdd56e30d5206e519e937a6681dc287117eded1ccc833c7d2caa28ec57bc3', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Part of the Romano-Gallic Baths of Entrammes lives on inside a church in Mayenne, and beneath it lies a hypocaust in good condition, proof of 2nd century thermal baths discovered in 1987."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "part of the baths was incorporated into a church [S2]; the baths are in Entrammes, Mayenne [S1]; a hypocaust in good condition lies beneath the church [S2, S5]; the hypocaust confirms the presence of thermal baths of the 2nd century [S5]; the remains were discovered in 1987 [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Romano-Gallic Baths of Entrammes are Gallo-Roman thermal baths in Entrammes, Mayenne, France [SUPPORTED: https://en.wikipedia.org/wiki/Romano-Gallic_Baths_of_Entrammes]; Part of the baths was incorporated into a church [SUPPORTED: https://en.wikipedia.org/wiki/Romano-Gallic_Baths_of_Entrammes]; A hypocaust in good condition lies beneath the church [SUPPORTED: https://en.wikipedia.org/wiki/Romano-Gallic_Baths_of_Entrammes]; The hypocaust confirms thermal baths of the 2nd century [SUPPORTED: https://en.wikipedia.org/wiki/Romano-Gallic_Baths_of_Entrammes]; The baths were discovered in 1987 [SUPPORTED: https://en.wikipedia.org/wiki/Romano-Gallic_Baths_of_Entrammes]"}]'::jsonb),
    ('919ca5f2-4d3b-474a-b7f5-1b706473797c'::uuid, 'card_description', 'The only surviving Early-Christian catacombs in Gozo — a unique Roman burial site that has drawn scholarly attention for centuries.', 'Dug into Globigerina Limestone on a slope of Lunzjata Valley, the Għar Għerduf Catacombs are the only surviving early Christian catacombs in Gozo, with arcosolia hewn into their walls.', 'teaser-card-s009:919ca5f2-4d3b-474a-b7f5-1b706473797c:card_description', 'teaser-card-s009 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'c921bbdd77f08fa3933de2a12023f32e9ef9174c5077306c90f1473ec8fd7f94|aa11c9a19b38e027fcf6b0a9e87888041639d16e5e60864e6eb730d3ea0abdc9|aa11c9a19b38e027fcf6b0a9e87888041639d16e5e60864e6eb730d3ea0abdc9', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Dug into Globigerina Limestone on a slope of Lunzjata Valley, the Għar Għerduf Catacombs are the only surviving early Christian catacombs in Gozo, with arcosolia hewn into their walls."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the catacombs are dug into Globigerina Limestone [S3]; they lie on a slope of Lunzjata Valley [S3]; they are the only surviving early Christian catacombs in Gozo [S1]; arcosolia are hewn into the walls [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Għar Għerduf Catacombs are early Christian catacombs (a burial site) in Gozo, Malta [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ar_G%C4%A7erduf_catacombs]; They are the only surviving early Christian catacombs in Gozo [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ar_G%C4%A7erduf_catacombs]; The catacombs are dug into Globigerina Limestone [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ar_G%C4%A7erduf_catacombs]; They lie on a slope of Lunzjata Valley [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ar_G%C4%A7erduf_catacombs]; Arcosolia are hewn into the walls of the catacombs [SUPPORTED: https://en.wikipedia.org/wiki/G%C4%A7ar_G%C4%A7erduf_catacombs]"}]'::jsonb),
    ('91ad730f-4a6d-48c3-aa2d-e79d940878ca'::uuid, 'card_description', 'According to R. Chevallier, a member of Robert Bedon''s team, the dating of the aqueduct is uncertain, but estimated to be as old as about 150 AD.', 'Running underground in the Ain, the Roman Aqueduct of Vieu has been studied since the seventeenth century. By R. Chevallier''s account its date is uncertain, estimated as old as about 150 AD.', 'teaser-card-s009:91ad730f-4a6d-48c3-aa2d-e79d940878ca:card_description', 'teaser-card-s009 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '108403dd9b0037512fe434a73ba696877e18beec144c06cd7f522c434b6945eb|a332be67bb68734cca7bd3a80b0731f111194e85bb70c09178ba35b8ff1e4d06|a332be67bb68734cca7bd3a80b0731f111194e85bb70c09178ba35b8ff1e4d06', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Running underground in the Ain, the Roman Aqueduct of Vieu has been studied since the seventeenth century. By R. Chevallier''s account its date is uncertain, estimated as old as about 150 AD."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the aqueduct runs underground [S1]; it is in the Ain [S1]; it is Roman [S1]; it has been studied since the seventeenth century [S2]; according to R. Chevallier its date is uncertain [S3]; it is estimated to be as old as about 150 AD [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Roman Aqueduct of Vieu is a Roman aqueduct located in Vieu [SUPPORTED: https://en.wikipedia.org/wiki/Roman_aqueduct_of_Vieu]; The aqueduct is in the French department of Ain [SUPPORTED: https://en.wikipedia.org/wiki/Roman_aqueduct_of_Vieu]; The aqueduct runs underground [SUPPORTED: https://en.wikipedia.org/wiki/Roman_aqueduct_of_Vieu]; The aqueduct has been studied since the seventeenth century [SUPPORTED: https://en.wikipedia.org/wiki/Roman_aqueduct_of_Vieu]; The dating is given by R. Chevallier (a member of Robert Bedon''s team) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_aqueduct_of_Vieu]; By Chevallier''s account the date of the aqueduct is uncertain [SUPPORTED: https://en.wikipedia.org/wiki/Roman_aqueduct_of_Vieu]; Its date is estimated as old as about 150 AD [SUPPORTED: https://en.wikipedia.org/wiki/Roman_aqueduct_of_Vieu]"}]'::jsonb),
    ('92313299-3bb1-45c2-aa95-eb147b0269ba'::uuid, 'card_description', 'An Iron Age farmstead from around 800 BC that became a model for understanding how ordinary people lived in prehistoric Britain. Its grain storage pits reveal a sophisticated agricultural system.', 'In 1938 and 1939, trenches across Little Woodbury revealed a roundhouse, granaries and storage pits. From its postholes Gerhard Bersu argued roundhouses, not pits, were the Iron Age home.', 'teaser-card-s009:92313299-3bb1-45c2-aa95-eb147b0269ba:card_description', 'teaser-card-s009 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'e0b258b91b6073cafeec4f973c7940e2c2d47995cb75807f613655ca0474b80c|78317f8aba6f157d6e2958278e8879313cd78c7cdc961043679ca993417b0c08|78317f8aba6f157d6e2958278e8879313cd78c7cdc961043679ca993417b0c08', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In 1938 and 1939, trenches across Little Woodbury revealed a roundhouse, granaries and storage pits. From its postholes Gerhard Bersu argued roundhouses, not pits, were the Iron Age home."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site was excavated in 1938 and 1939 [S3]; the excavation used trenches across the site [S6]; the trenches revealed a roundhouse [S7]; the trenches revealed granaries and storage pits [S7]; Gerhard Bersu argued from the roundhouse postholes that roundhouses were the Iron Age home [S8]; earlier thinking held that people lived in pit-dwellings, so roundhouses rather than pits [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Little Woodbury is an Iron Age archaeological site (a settlement) in England [SUPPORTED: https://en.wikipedia.org/wiki/Little_Woodbury]; Little Woodbury was excavated in 1938 and 1939 (by Gerhard Bersu) [SUPPORTED: https://en.wikipedia.org/wiki/Little_Woodbury]; Trenches were dug across the site [SUPPORTED: https://en.wikipedia.org/wiki/Little_Woodbury]; The excavation revealed a roundhouse [SUPPORTED: https://en.wikipedia.org/wiki/Little_Woodbury]; The excavation revealed granaries and storage pits [SUPPORTED: https://en.wikipedia.org/wiki/Little_Woodbury]; Gerhard Bersu argued from the roundhouse postholes that roundhouses were the Iron Age domestic building [SUPPORTED: https://en.wikipedia.org/wiki/Little_Woodbury]; Roundhouses, not pits (pit-dwellings), were the Iron Age home [SUPPORTED: https://en.wikipedia.org/wiki/Little_Woodbury]"}]'::jsonb),
    ('93af4a1c-5f49-4daf-a488-65d5be9a355a'::uuid, 'card_description', 'A 74 km road through Norfolk and Suffolk follows a Roman-era route that writers have argued predates Roman arrival. Its name comes from the medieval word pedder — meaning a travelling merchant.', 'From Knettishall Heath in Suffolk, the Peddars Way follows a Roman road for 46 miles to meet the Norfolk Coast Path. Its name comes from pedder, Middle English for an itinerant trader.', 'teaser-card-s009:93af4a1c-5f49-4daf-a488-65d5be9a355a:card_description', 'teaser-card-s009 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '8a0d9babbc6ea24895950ec977ed966fd47b0d41fe94a9e3a41e97aa007fc9be|6ff12d3ed9deb3a2ba74418e9cf9d5e2087f697f7d8415c982a5becb776e86f8|6ff12d3ed9deb3a2ba74418e9cf9d5e2087f697f7d8415c982a5becb776e86f8', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "From Knettishall Heath in Suffolk, the Peddars Way follows a Roman road for 46 miles to meet the Norfolk Coast Path. Its name comes from pedder, Middle English for an itinerant trader."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Peddars Way starts at Knettishall Heath in Suffolk [S5]; it follows the route of a Roman road [S2]; it is 46 miles long [S2]; it meets the Norfolk Coast Path [S5]; its name comes from Middle English pedder [S3]; pedder means an itinerant trader [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Peddars Way is a long-distance footpath (trail) in England [SUPPORTED: https://en.wikipedia.org/wiki/Peddars_Way]; The Peddars Way starts at Knettishall Heath in Suffolk [SUPPORTED: https://www.nationaltrail.co.uk/en_GB/trails/peddars-way-and-norfolk-coast-path/]; It follows the route of a Roman road [SUPPORTED: https://www.nationaltrail.co.uk/en_GB/trails/peddars-way-and-norfolk-coast-path/]; It is 46 miles long [SUPPORTED: https://www.nationaltrail.co.uk/en_GB/trails/peddars-way-and-norfolk-coast-path/]; It meets the Norfolk Coast Path [SUPPORTED: https://www.nationaltrail.co.uk/en_GB/trails/peddars-way-and-norfolk-coast-path/]; The name Peddars comes from Middle English pedder, meaning an itinerant trader [SUPPORTED: https://en.wikipedia.org/wiki/Peddars_Way]"}]'::jsonb),
    ('941b3241-8cc0-408b-a1be-2ee5cd8ad6f7'::uuid, 'card_description', 'Petroglyphs on sandstone blocks up to 12 metres high, from the Upper Paleolithic to medieval times. The oldest images may be over 20,000 years old.', 'Sandstone blocks up to twelve meters high rise in the Molochna River valley. Only inside the caves and grottoes of Kamyana Mohyla, many still filled with sand, are petroglyphs found.', 'teaser-card-s009:941b3241-8cc0-408b-a1be-2ee5cd8ad6f7:card_description', 'teaser-card-s009 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '0fa0a2cbcfc6dba8cf2dfc0dc84048e3b7f939933c22790260fc798847422bd0|ebd83b425e4998c4e8b5c055747cd99d5cf8cca5c6992da8ad92125a4d362689|ebd83b425e4998c4e8b5c055747cd99d5cf8cca5c6992da8ad92125a4d362689', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Sandstone blocks up to twelve meters high rise in the Molochna River valley. Only inside the caves and grottoes of Kamyana Mohyla, many still filled with sand, are petroglyphs found."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "sandstone blocks stand at the site [S2]; the blocks are up to twelve metres high [S2]; the site lies in the Molochna River valley [S1]; petroglyphs are found only inside the caves and grottoes [S3]; many of the caves and grottoes are still filled with sand [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Kamyana Mohyla is an archaeological site (a sandstone outcrop with petroglyphs) in the Molochna River valley, Ukraine [SUPPORTED: https://en.wikipedia.org/wiki/Kamyana_Mohyla]; Sandstone blocks up to twelve meters high rise at the site [SUPPORTED: https://en.wikipedia.org/wiki/Kamyana_Mohyla]; Petroglyphs are found in the caves and grottoes of Kamyana Mohyla [SUPPORTED: https://www.encyclopediaofukraine.com/display.asp?linkpath=pages%5CK%5CA%5CKamianaMohyla.htm]; Many of the caves and grottoes are still filled with sand [SUPPORTED: https://en.wikipedia.org/wiki/Kamyana_Mohyla]; Petroglyphs are found ONLY inside the caves and grottoes (none on exposed slabs or cornices outside them) [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('944099e9-5dfb-435f-a1a2-0c87eb4660be'::uuid, 'card_description', 'The barrow was constructed by the Funnelbeaker culture around 3500 BC and is marked out by 47 megaliths.', 'Its name means both Church of the Troll and Church of Sorcery: Troldkirken, a long barrow built by the Funnelbeaker culture around 3500 BC, marked out by 47 megaliths with a dolmen on top.', 'teaser-card-s009:944099e9-5dfb-435f-a1a2-0c87eb4660be:card_description', 'teaser-card-s009 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '22e269585c59612282a615e786eeb0ce56af3ea1b6247d6627ae9110cb9cf105|4c2b9d482524e779f9007dd9a456f02d92710bb4f9430890cb60e93f1ccf1ceb|4c2b9d482524e779f9007dd9a456f02d92710bb4f9430890cb60e93f1ccf1ceb', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Its name means both Church of the Troll and Church of Sorcery: Troldkirken, a long barrow built by the Funnelbeaker culture around 3500 BC, marked out by 47 megaliths with a dolmen on top."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the name Troldkirken means Church of the Troll [S5]; the name also means Church of Sorcery [S5]; Troldkirken is a long barrow [S1]; it was built by the Funnelbeaker culture [S2]; it was built around 3500 BC [S2]; it is marked out by 47 megaliths [S2]; a dolmen sits on top of the barrow [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Troldkirken is a long barrow (a Stone Age tomb mound) in Denmark [SUPPORTED: https://en.wikipedia.org/wiki/Troldkirken]; The name Troldkirken means Church of the Troll [SUPPORTED: https://en.wikipedia.org/wiki/Troldkirken]; The name Troldkirken also means Church of Sorcery [SUPPORTED: https://en.wikipedia.org/wiki/Troldkirken]; The barrow was built by the Funnelbeaker culture [SUPPORTED: https://en.wikipedia.org/wiki/Troldkirken]; The barrow dates to around 3500 BC [SUPPORTED: https://en.wikipedia.org/wiki/Troldkirken]; The barrow is marked out by 47 megaliths [SUPPORTED: https://en.wikipedia.org/wiki/Troldkirken]; A dolmen stands on top of the barrow [SUPPORTED: https://en.wikipedia.org/wiki/Troldkirken]"}]'::jsonb),
    ('94cf34a3-2cf8-41e9-adf3-80c288b4f972'::uuid, 'card_description', 'A Neolithic and Bronze Age cemetery from 3300-800 BC with clusters of round barrows. Each mound held individual burials — a shift from the earlier communal tomb tradition.', 'On Codford Down, only a bell barrow and five of ten bowl barrows survive at the Aston Valley Barrow Cemetery, where digs revealed Bronze Age and some possible Saxon urned cremations.', 'teaser-card-s009:94cf34a3-2cf8-41e9-adf3-80c288b4f972:card_description', 'teaser-card-s009 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '7ac60f2a0a234e9e677ff9a2ab6dd3ec04354eb130454f63ba86b31bcaa60ef9|41df1dba1be289c25d4f5393d560b5fb07619c4062e81c46e0fa3f78a9dec09f|41df1dba1be289c25d4f5393d560b5fb07619c4062e81c46e0fa3f78a9dec09f', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On Codford Down, only a bell barrow and five of ten bowl barrows survive at the Aston Valley Barrow Cemetery, where digs revealed Bronze Age and some possible Saxon urned cremations."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the cemetery lies on Codford Down [S1]; only a bell barrow and five bowl barrows survive [S2]; there were originally ten bowl barrows [S2]; excavations revealed Bronze Age urned cremations [S4]; excavations revealed some possible Saxon urned cremations [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Aston Valley Barrow Cemetery is a group of Bronze Age barrows (burial mounds) in England [SUPPORTED: https://en.wikipedia.org/wiki/Aston_Valley_Barrow_Cemetery]; The barrows lie on Codford Down, in Wiltshire [SUPPORTED: https://en.wikipedia.org/wiki/Aston_Valley_Barrow_Cemetery]; There were originally ten bowl barrows [SUPPORTED: https://en.wikipedia.org/wiki/Aston_Valley_Barrow_Cemetery]; Only five of the ten bowl barrows survive [SUPPORTED: https://en.wikipedia.org/wiki/Aston_Valley_Barrow_Cemetery]; The bell barrow survives [SUPPORTED: https://en.wikipedia.org/wiki/Aston_Valley_Barrow_Cemetery]; Excavations revealed Bronze Age urned cremations [SUPPORTED: https://en.wikipedia.org/wiki/Aston_Valley_Barrow_Cemetery]; Excavations also revealed some possible Saxon urned cremations [SUPPORTED: https://en.wikipedia.org/wiki/Aston_Valley_Barrow_Cemetery]"}]'::jsonb),
    ('94fc8fb4-4792-418c-bee0-65c3ec4b8a71'::uuid, 'card_description', 'A stone-and-earth rampart 7 m wide curves southeast from Salters Nick at Shaftoe Crags, enclosing an irregular area supplemented by natural crags. The site spans Iron Age and Romano-period use.', 'About 8 miles west of Morpeth, the Shaftoe Crags Settlement holds remains from the Iron Age and Romano-British periods, yet any roundhouses of that time lie obscured by later buildings.', 'teaser-card-s009:94fc8fb4-4792-418c-bee0-65c3ec4b8a71:card_description', 'teaser-card-s009 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '62cee67880f2d1ccaeee9920cf2f99b084094813b59897d732429e22c37a0751|eeb0e3cb8e2c58d9dd23bc6d5e3359fed884475b15df2d4dd1059e46c4a69eab|eeb0e3cb8e2c58d9dd23bc6d5e3359fed884475b15df2d4dd1059e46c4a69eab', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "About 8 miles west of Morpeth, the Shaftoe Crags Settlement holds remains from the Iron Age and Romano-British periods, yet any roundhouses of that time lie obscured by later buildings."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is about 8 miles west of Morpeth [S1]; it holds remains from the Iron Age and Romano-British periods [S2]; any roundhouses from that period are obscured by later buildings [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Shaftoe Crags Settlement is an archaeological site (a native settlement) in Northumberland, England, about 8 miles west of Morpeth [SUPPORTED: https://en.wikipedia.org/wiki/Shaftoe_Crags_Settlement]; The site holds remains from the Iron Age and Romano-British periods [SUPPORTED: https://en.wikipedia.org/wiki/Shaftoe_Crags_Settlement]; Any Iron Age roundhouses are obscured by the later buildings [SUPPORTED: https://en.wikipedia.org/wiki/Shaftoe_Crags_Settlement]"}]'::jsonb),
    ('964d2a78-6209-4f94-be74-761d59bfd0cc'::uuid, 'card_description', 'Built around 2400 BC near Pendeen, this Neolithic quoit''s capstone still balances on its uprights after over 4,000 years. A round barrow 10.6 meters in diameter originally covered it.', 'On a ridge above heather moorland and the open sea, Chûn Quoit raises its mushroom-domed capstone on four great slabs, a cup mark on top. Examined in 1871, it gave up no significant finds.', 'teaser-card-s009:964d2a78-6209-4f94-be74-761d59bfd0cc:card_description', 'teaser-card-s009 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'cd099199d91e24ca4b8a6a2deb1642fa4205609a4f2f62fcc3be600a26c75cca|0c6d6a38d98ffdebe6a026c9a9f7f15b0cda78468d2cbc6932296cf142646e52|0c6d6a38d98ffdebe6a026c9a9f7f15b0cda78468d2cbc6932296cf142646e52', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a ridge above heather moorland and the open sea, Chûn Quoit raises its mushroom-domed capstone on four great slabs, a cup mark on top. Examined in 1871, it gave up no significant finds."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the quoit stands on a ridge [S3]; it overlooks heather moorland and the open sea [S3]; its capstone is mushroom-domed [S5]; the capstone is supported by four substantial slabs [S7]; there is a cup mark on top of the capstone [S6]; the site was examined in 1871 [S8]; no significant finds were made [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Chûn Quoit is a Neolithic quoit (dolmen, a megalithic tomb) in western Cornwall, England [SUPPORTED: https://en.wikipedia.org/wiki/Ch%C3%BBn_Quoit]; It stands on a ridge [SUPPORTED: https://en.wikipedia.org/wiki/Ch%C3%BBn_Quoit]; It overlooks heather moorland [SUPPORTED: https://en.wikipedia.org/wiki/Ch%C3%BBn_Quoit]; It overlooks the open sea [SUPPORTED: https://en.wikipedia.org/wiki/Ch%C3%BBn_Quoit]; It has a mushroom-domed capstone [SUPPORTED: https://en.wikipedia.org/wiki/Ch%C3%BBn_Quoit]; The capstone is raised on four great slabs [SUPPORTED: https://en.wikipedia.org/wiki/Ch%C3%BBn_Quoit]; There is a cup mark on top of the capstone [SUPPORTED: https://en.wikipedia.org/wiki/Ch%C3%BBn_Quoit]; The site was examined in 1871 [SUPPORTED: https://en.wikipedia.org/wiki/Ch%C3%BBn_Quoit]; The 1871 examination yielded no significant finds [SUPPORTED: https://en.wikipedia.org/wiki/Ch%C3%BBn_Quoit]"}]'::jsonb),
    ('9724373d-f4f0-4a4b-b460-d01dd5b4b2ee'::uuid, 'card_description', 'Plateau fort concealed in heavy Hampshire woodland, defended by three concentric bank-and-ditch rings at 65 metres altitude. The earthworks are eroded but still visible on close inspection.', 'In thick woods by the River Loddon, the three bank and ditch fortifications of Bullsdown Camp, an Iron Age plateau fort at a height of 65m, show themselves only to close inspection.', 'teaser-card-s009:9724373d-f4f0-4a4b-b460-d01dd5b4b2ee:card_description', 'teaser-card-s009 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '178bd80bfbbac23d49411cb9103ef282de69303ea907b24feeef39e1bb6dadab|b3545d203675d76adfd22749f83e6847cf68c60ed033e9dd9ffbd26d467aa0ca|b3545d203675d76adfd22749f83e6847cf68c60ed033e9dd9ffbd26d467aa0ca', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In thick woods by the River Loddon, the three bank and ditch fortifications of Bullsdown Camp, an Iron Age plateau fort at a height of 65m, show themselves only to close inspection."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is heavily wooded [S2]; the River Loddon lies close by [S3]; the camp has three bank and ditch fortifications [S2]; the camp is an Iron Age plateau fort [S1]; it lies at a height of 65m [S4]; the fortifications can only be observed by close inspection [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Bullsdown Camp is a plateau fort in Hampshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Bullsdown_Camp]; The fort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Bullsdown_Camp]; The site lies in thick woods (is heavily wooded) [SUPPORTED: https://en.wikipedia.org/wiki/Bullsdown_Camp]; The River Loddon lies close by the site [SUPPORTED: https://en.wikipedia.org/wiki/Bullsdown_Camp]; The site has three bank and ditch fortifications [SUPPORTED: https://en.wikipedia.org/wiki/Bullsdown_Camp]; The fortifications show themselves only to close inspection [SUPPORTED: https://en.wikipedia.org/wiki/Bullsdown_Camp]; The plateau lies at a height of 65 m [SUPPORTED: https://en.wikipedia.org/wiki/Bullsdown_Camp]"}]'::jsonb),
    ('9760e579-1005-4b8f-bf08-b9be81a716da'::uuid, 'card_description', NULL, 'In the valley of the Luhe lies the Oldendorfer Totenstatt, six burial mounds and megalith sites. Its chambers held Funnelbeaker, Globular amphora and Corded Ware relics, layer on layer.', 'teaser-card-s009:9760e579-1005-4b8f-bf08-b9be81a716da:card_description', 'teaser-card-s009 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '01af6379685bdac2e577af8e5c97b8e3ea1ee3861005b6ee8c8325447ee3957e|ee1e249a44a10bc99a75919ca00b059d69e9c052607ca6fb7b114866e21348f9|ee1e249a44a10bc99a75919ca00b059d69e9c052607ca6fb7b114866e21348f9', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In the valley of the Luhe lies the Oldendorfer Totenstatt, six burial mounds and megalith sites. Its chambers held Funnelbeaker, Globular amphora and Corded Ware relics, layer on layer."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Oldendorfer Totenstatt lies in the valley of the Luhe (River Luhe) [S1]; the site is six burial mounds and megalith sites [S1]; the chambers of the site (sites 2 and 4) held relics of the Funnelbeaker, Globular amphora and Corded Ware cultures [S8]; the relics lay at different levels (layer on layer) [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Oldendorfer Totenstatt is a prehistoric burial ground of megalith sites (dolmens and tumuli), a tomb complex rather than a settlement or fort [SUPPORTED: https://en.wikipedia.org/wiki/Oldendorfer_Totenstatt]; It lies in the valley of the Luhe (River Luhe, Lower Saxony, Germany) [SUPPORTED: https://en.wikipedia.org/wiki/Oldendorfer_Totenstatt]; The Oldendorfer Totenstatt consists of six burial mounds and megalith sites [SUPPORTED: https://en.wikipedia.org/wiki/Oldendorfer_Totenstatt]; Its chambers held relics of the Funnelbeaker, Globular amphora and Corded Ware cultures [SUPPORTED: https://en.wikipedia.org/wiki/Oldendorfer_Totenstatt]; The relics lay layer on layer (at different levels, in separate layers) [SUPPORTED: https://en.wikipedia.org/wiki/Oldendorfer_Totenstatt]"}]'::jsonb),
    ('9789eadf-a133-43dc-9f8e-2d7f7818ecc2'::uuid, 'card_description', NULL, 'In Sardinia, the Necropolis of Li Muri holds five stone cists, four ringed by stone circles. The dead were laid there with pottery, hatchets and bead necklaces of steatite and gemstones.', 'teaser-card-s009:9789eadf-a133-43dc-9f8e-2d7f7818ecc2:card_description', 'teaser-card-s009 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'ba6d1f18c14028b652b54746e151185aa0fb52e784a3a6b38ffdd980df068de8|9bc8939a99a37da18b83eecfc3d47fb0e6831d2e42e1d39936d25103f37365a9|9bc8939a99a37da18b83eecfc3d47fb0e6831d2e42e1d39936d25103f37365a9', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In Sardinia, the Necropolis of Li Muri holds five stone cists, four ringed by stone circles. The dead were laid there with pottery, hatchets and bead necklaces of steatite and gemstones."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Necropolis of Li Muri is in Sardinia [S1]; it holds five stone cists [S2]; four of the cists are ringed by stone circles [S3]; the dead were laid there (interred in the cists) [S4]; the dead were accompanied by pottery [S5]; the dead were accompanied by hatchets [S5]; the dead were accompanied by bead necklaces of steatite and gemstones [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Necropolis of Li Muri is a necropolis (burial site), an archaeological site in the municipality of Arzachena [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Li_Muri]; The necropolis is in Sardinia [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Li_Muri]; The necropolis holds five stone cists [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Li_Muri]; Four of the five cists are ringed by stone circles [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Li_Muri]; The dead were laid (interred) inside the cists [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Li_Muri]; The dead were laid there with pottery as grave goods [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Li_Muri]; The dead were laid there with hatchets as grave goods [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Li_Muri]; The dead were laid there with bead necklaces of steatite and gemstones [SUPPORTED: https://en.wikipedia.org/wiki/Necropolis_of_Li_Muri]"}]'::jsonb),
    ('98299c91-a01b-4dfc-bc31-f8f8ce1b84a5'::uuid, 'card_description', 'A well-preserved Roman temple dedicated to Azizos, later converted into a church. Two phases of Christianization altered the ancient structure.', 'The Bziza Roman Temple, well preserved from the first century AD, was dedicated to Azizos, the morning star personified. At its back, images of the deity once stood in the adyton.', 'teaser-card-s009:98299c91-a01b-4dfc-bc31-f8f8ce1b84a5:card_description', 'teaser-card-s009 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'bca5ef35ef8eb9111bef01e3ad11a1085bd2dc86b290376df6ed147982020ed8|b11556c33a0ae05ff648723ee88eaaa89069a460721766dcb522285dbddbdfab|b11556c33a0ae05ff648723ee88eaaa89069a460721766dcb522285dbddbdfab', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Bziza Roman Temple, well preserved from the first century AD, was dedicated to Azizos, the morning star personified. At its back, images of the deity once stood in the adyton."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the temple is well preserved [S1]; it dates from the first century AD [S1, S4]; it was dedicated to Azizos [S1]; Azizos is the morning star personified [S1]; at the back of the temple lies the adyton [S3]; images of the deity once stood in the adyton [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Bziza Roman Temple is a Roman temple (a building dedicated to a deity), in Lebanon [SUPPORTED: https://en.wikipedia.org/wiki/Roman_temple_of_Bziza]; The temple is well preserved [SUPPORTED: https://en.wikipedia.org/wiki/Roman_temple_of_Bziza]; The temple dates from the first century AD [SUPPORTED: https://en.wikipedia.org/wiki/Roman_temple_of_Bziza]; The temple was dedicated to Azizos [SUPPORTED: https://en.wikipedia.org/wiki/Roman_temple_of_Bziza]; Azizos is the morning star personified (a personification of the morning star) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_temple_of_Bziza]; At the back of the temple, images of the deity once stood in the adyton [SUPPORTED: https://en.wikipedia.org/wiki/Roman_temple_of_Bziza]"}]'::jsonb),
    ('98921574-7b56-4c66-af63-27316f3b82d3'::uuid, 'card_description', 'A Prehistoric site on a rocky outcrop with Neolithic and Iron Age settlements. Two different cultures chose this same hilltop millennia apart.', 'On the St David''s peninsula rises Clegyr Boia, a rocky hilltop that yielded Neolithic pottery and polished stone axes, and later became the stronghold of a 6th-century CE Irish pirate.', 'teaser-card-s009:98921574-7b56-4c66-af63-27316f3b82d3:card_description', 'teaser-card-s009 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '51d8c89b37c44021b98c1d860afaab6e3a45f192ee823fe0d98859d026ae319b|de1292203a98691638ab0632ebe25767a06a12e5340d06f890ee7f0536d7b325|de1292203a98691638ab0632ebe25767a06a12e5340d06f890ee7f0536d7b325', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the St David''s peninsula rises Clegyr Boia, a rocky hilltop that yielded Neolithic pottery and polished stone axes, and later became the stronghold of a 6th-century CE Irish pirate."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Clegyr Boia is on the St David''s peninsula [S1]; it is a rocky hilltop [S2]; the site yielded Neolithic pottery [S5]; the site yielded polished stone axes [S5]; the outcrop later became the stronghold of an Irish pirate [S3]; the pirate lived in the 6th century CE [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Clegyr Boia is a prehistoric hilltop site (settlement/hillfort) in Wales [SUPPORTED: https://en.wikipedia.org/wiki/Clegyr_Boia]; Clegyr Boia is on the St David''s peninsula [SUPPORTED: http