    ('9ae31b41-d78d-44da-824d-43487ec611f0'::uuid, 'card_description', NULL, 'On the northern edge of the South Downs, the ditches of Combe Hill held Ebbsfleet ware pottery and three polished stone axes, the axes laid down perhaps not long after their ditch was dug.', 'teaser-card-s009:9ae31b41-d78d-44da-824d-43487ec611f0:card_description', 'teaser-card-s009 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '7a91fcc4116dd6c02dc21dbad605315fdfa71e4aaa4d23865e50df5ba07ca4ad|8a500c9f9b45775feecb002485dafb40dd2a54493d242c96c425d61bd1be5c18|8a500c9f9b45775feecb002485dafb40dd2a54493d242c96c425d61bd1be5c18', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the northern edge of the South Downs, the ditches of Combe Hill held Ebbsfleet ware pottery and three polished stone axes, the axes laid down perhaps not long after their ditch was dug."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Combe Hill lies on the northern edge of the South Downs [S1]; its ditches held Ebbsfleet ware pottery [S5]; its ditches held three polished stone axes [S6]; the axes were laid down (deposited) perhaps not long after their ditch was dug [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Combe Hill is a ditched earthwork enclosure (a Neolithic causewayed enclosure) - the kind of place the text is about [SUPPORTED: https://en.wikipedia.org/wiki/Combe_Hill,_East_Sussex]; Combe Hill lies on the northern edge of the South Downs [SUPPORTED: https://en.wikipedia.org/wiki/Combe_Hill,_East_Sussex]; Ebbsfleet ware pottery was found in a ditch 