    ('9aedc6a3-1681-4ee3-8d6c-4386de4bba1d'::uuid, 'card_description', 'A 2nd-century AD amphitheatre half-carved into rock, half-built in limestone, seating over 10,000. It is the largest Roman monument on the island.', 'Half carved into the rock, the Roman Amphitheatre of Cagliari could house up to 8,000 spectators. Its arena saw gladiators, fights between men and animals, and public executions.', 'teaser-card-s009:9aedc6a3-1681-4ee3-8d6c-4386de4bba1d:card_description', 'teaser-card-s009 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '692db95e67f8e62a29fb97f8d7efffb9ebe1479dac82e6605c0aef56bb0c5222|045ec4955959a3cbe1637db5427ee4ca82d7b87102a1566a7e6cd02ac71fcdd3|045ec4955959a3cbe1637db5427ee4ca82d7b87102a1566a7e6cd02ac71fcdd3', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Half carved into the rock, the Roman Amphitheatre of Cagliari could house up to 8,000 spectators. Its arena saw gladiators, fights between men and animals, and public executions."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the amphitheatre was half carved into the rock [S2]; it could house up to 8,000 spectators [S6]; it saw gladiators fighting [S4]; it saw fights between men and animals [S4]; it saw public executions [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Roman Amphitheatre of Cagliari is an ancient Roman amphitheatre in Cagliari, Sardinia, Italy - the kind of place the text is about [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Amphitheatre_of_Cagliari]; The amphitheatre was half carved into the rock [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Amphitheatre_of_Cagliari]; The amphitheatre could house up to 8,000 spectators (a stated estimate: English Wikipedia gives 8,000; Italian Wikipedia says 8,000 or about 10,000 and sardegnaturismo.it says ten thousand, so the figure is an estimate, not settled) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Amphitheatre_of_Cagliari]; The arena saw gladiators fight [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Amphitheatre_of_Cagliari]; The arena saw fights between men and animals [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Amphitheatre_of_Cagliari]; The amphitheatre was a place of public executions [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Amphitheatre_of_Cagliari]"}]'::jsonb),
    ('9b10cebe-56ec-42cd-9f05-fa9c679c2bce'::uuid, 'card_description', 'The town was established around 122 AD as one of several Roman localities called Alauna.', 'Maryport holds the remains of a Roman fort, a command and supply base for the defences at the western end of Hadrian''s Wall. Geomagnetic surveys have revealed a large Roman town around it.', 'teaser-card-s009:9b10cebe-56ec-42cd-9f05-fa9c679c2bce:card_description', 'teaser-card-s009 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '3d207ff8abefa45b7883fbe93b30720ad395a3813aa874874e09e13a6cb5fa83|250cb8b7051e2c78c91a3a3bbc32a95809473109aa7050c243de405463daf9e0|250cb8b7051e2c78c91a3a3bbc32a95809473109aa7050c243de405463daf9e0', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Maryport holds the remains of a Roman fort, a command and supply base for the defences at the western end of Hadrian''s Wall. Geomagnetic surveys have revealed a large Roman town around it."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Maryport holds the remains of a Roman fort [S6]; the Roman settlement/fort was a command and supply base [S5]; the base served the defences at the western end of Hadrian''s Wall [S5]; geomagnetic surveys have revealed a large Roman town [S7]; the Roman town surrounds the fort [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Maryport holds the substantial remains of a Roman fort (Alauna) - the kind of place the text is about [SUPPORTED: https://en.wikipedia.org/wiki/Maryport]; The fort was a command and supply base [SUPPORTED: https://en.wikipedia.org/wiki/Maryport]; The defences it served lay at the western end of Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Alauna_(Maryport)]; Geomagnetic surveys have revealed a Roman town at Maryport [SUPPORTED: https://www.maryporttowncouncil.gov.uk/local-attractions/roman-maryport/]; The Roman town is large and lies around the fort [SUPPORTED: https://en.wikipedia.org/wiki/Alauna_(Maryport)]"}]'::jsonb),
    ('9b546e2f-9bd2-4c84-a6e4-9acfa6c6480a'::uuid, 'card_description', 'The fort was built about 2,500 years ago, and fell into disuse until the early centuries AD when it was possibly re-occupied to protect the nearby tin mines.', 'Chûn Castle, ''the house on the downs'', was built about 2,500 years ago beside the prehistoric Tinners'' Way, and possibly re-occupied in the early centuries AD to protect nearby tin mines.', 'teaser-card-s009:9b546e2f-9bd2-4c84-a6e4-9acfa6c6480a:card_description', 'teaser-card-s009 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'fba2d2268549dc3a58789450630d265a8e856032b1b94953e7950f7ae645c9fb|cb401fda5c15db90944c0bdcec79f639a5dfb491b38d06c2be20a3d2f17f2283|cb401fda5c15db90944c0bdcec79f639a5dfb491b38d06c2be20a3d2f17f2283', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Chûn Castle, ''the house on the downs'', was built about 2,500 years ago beside the prehistoric Tinners'' Way, and possibly re-occupied in the early centuries AD to protect nearby tin mines."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the name Chûn means ''the house on the downs'' [S4]; the fort was built about 2,500 years ago [S2]; it stands beside a prehistoric trackway [S3]; the trackway is (was) known as the Tinners'' Way [S3]; the fort was possibly re-occupied in the early centuries AD [S2]; the possible re-occupation was to protect nearby tin mines [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Chûn Castle is a hill fort (a fortified hilltop enclosure, an Iron Age hillfort) near Penzance in Cornwall, England - the kind of place the text is about [SUPPORTED: https://en.wikipedia.org/wiki/Ch%C3%BBn_Castle]; The name Chûn means ''the house on the downs'' (Cornish Chi an Woon) [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Ch%C3%BBn_Castle]; The castle was built about 2,500 years ago (rounded Wikipedia figure; Historic England-derived text on the Megalithic Portal dates the main occupation from the 3rd century BC) [SUPPORTED: https://en.wikipedia.org/wiki/Ch%C3%BBn_Castle]; It stands beside the prehistoric trackway known as the Tinners'' Way [SUPPORTED: https://en.wikipedia.org/wiki/Ch%C3%BBn_Castle]; It was possibly re-occupied in the early centuries AD (Wikipedia''s wording; Historic England-derived text on the Megalithic Portal gives a possible re-occupation in the 5th or 6th centuries AD) [SUPPORTED: https://en.wikipedia.org/wiki/Ch%C3%BBn_Castle]; The re-occupation was possibly to protect the nearby tin mines [SUPPORTED: https://en.wikipedia.org/wiki/Ch%C3%BBn_Castle]"}]'::jsonb),
    ('9ba07ea3-0efb-41eb-a65d-e7c5d4c2fe2d'::uuid, 'card_description', NULL, 'Locals call it the Nipple for the mound on its summit: Twmbarlwm, a 419 m hill topped by what is presumed to be an Iron Age hillfort, believed to have been built by the Celtic Silures.', 'teaser-card-s009:9ba07ea3-0efb-41eb-a65d-e7c5d4c2fe2d:card_description', 'teaser-card-s009 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'a362880ba51ee71de4b368a5ca6ca3463eb114c1c0645f9724f1d9ea08ca1528|854da8b534db45ec0512ec4bc9c34c3826f88dadfa388b6b9b336de4bd051fd2|854da8b534db45ec0512ec4bc9c34c3826f88dadfa388b6b9b336de4bd051fd2', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Locals call it the Nipple for the mound on its summit: Twmbarlwm, a 419 m hill topped by what is presumed to be an Iron Age hillfort, believed to have been built by the Celtic Silures."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "locals call the hill the Nipple [S1]; the name comes from the mound on its summit [S1]; Twmbarlwm is a hill [S1]; it is 419 m high [S2]; near the top are the remains of what is presumed to be an Iron Age hillfort [S3]; the hillfort is believed to have been built by the Silures [S3]; the Silures were a Celtic tribe [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Twmbarlwm is a hillfort (the remains of a fort at the top of a hill) [SUPPORTED: https://en.wikipedia.org/wiki/Twmbarlwm]; Twmbarlwm is in Wales [SUPPORTED: https://en.wikipedia.org/wiki/Twmbarlwm]; The hillfort is presumed (not certain) to be of the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Twmbarlwm]; Locals call the hill the Nipple [SUPPORTED: https://en.wikipedia.org/wiki/Twmbarlwm]; The nickname comes from the mound on the hill''s summit [SUPPORTED: https://en.wikipedia.org/wiki/Twmbarlwm]; Twmbarlwm is a 419 m hill [SUPPORTED: https://cy.wikipedia.org/wiki/Twmbarlwm]; The hillfort is believed to have been built by the Silures [SUPPORTED: https://en.wikipedia.org/wiki/Twmbarlwm]; The Silures were a Celtic tribe [SUPPORTED: https://en.wikipedia.org/wiki/Twmbarlwm]"}]'::jsonb),
    ('9bedafde-94b7-40d2-a064-4130c224d7ef'::uuid, 'card_description', 'A roughly 5,000-year-old menhir resculpted into a Christian cross, reportedly by the missionary Willibrord. Niches for saint figures were chiselled into the ancient stone.', 'By a wayside on the Ferschweiler Plateau stands the Fraubillen Cross, a roughly 5,000-year-old menhir that, according to tradition, the missionary Willibrord reshaped by hand into a cross.', 'teaser-card-s009:9bedafde-94b7-40d2-a064-4130c224d7ef:card_description', 'teaser-card-s009 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '377ae957de94ff35bc0ce285a73c04c6052fea5ab88cbac1ecbe1caf4c4370a5|5fbd9c2a6df7260679431266dc5672f5f4aa355f4ae726151c2942682b65de12|5fbd9c2a6df7260679431266dc5672f5f4aa355f4ae726151c2942682b65de12', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "By a wayside on the Ferschweiler Plateau stands the Fraubillen Cross, a roughly 5,000-year-old menhir that, according to tradition, the missionary Willibrord reshaped by hand into a cross."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Fraubillen Cross stands by a wayside [S2]; it stands on the Ferschweiler Plateau [S2]; it is a menhir [S1]; the menhir is roughly 5,000 years old [S3]; according to tradition the missionary Willibrord reshaped it by hand into a cross [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Fraubillen Cross is a menhir (a standing stone) that has been resculpted into a cross [SUPPORTED: https://en.wikipedia.org/wiki/Fraubillen_cross]; It stands on the Ferschweiler Plateau [SUPPORTED: https://en.wikipedia.org/wiki/Fraubillen_cross]; It stands by a wayside [SUPPORTED: https://en.wikipedia.org/wiki/Fraubillen_cross]; The menhir is roughly 5,000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Fraubillen_cross]; According to tradition, Willibrord reshaped the menhir into a cross [SUPPORTED: https://en.wikipedia.org/wiki/Fraubillen_cross]; Willibrord was a missionary [SUPPORTED: https://en.wikipedia.org/wiki/Fraubillen_cross]; Willibrord reshaped the stone by hand [SUPPORTED: https://de.wikipedia.org/wiki/Fraubillenkreuz]; The menhir was reshaped into a cross [SUPPORTED: https://en.wikipedia.org/wiki/Fraubillen_cross]"}]'::jsonb),
    ('9c128b05-d7c1-45f8-873d-bc5f96d04751'::uuid, 'card_description', 'Capocorb Vell is a talayotic site located about 12 kilometres from Llucmajor on the island of Mallorca.', 'About 12 kilometres from Llucmajor on Mallorca lies Capocorb Vell, one of the most highly excavated talayotic sites in the Balearic Islands, with several talayots to its north-east.', 'teaser-card-s009:9c128b05-d7c1-45f8-873d-bc5f96d04751:card_description', 'teaser-card-s009 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '27a496b47af546c7dd81c2398273db4874f4fc0c4e81bb55009932f3f41315e9|81d55400b4bc434af1f9fe8836252e73fe0902fe529951102ed3f07fe245d0af|81d55400b4bc434af1f9fe8836252e73fe0902fe529951102ed3f07fe245d0af', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "About 12 kilometres from Llucmajor on Mallorca lies Capocorb Vell, one of the most highly excavated talayotic sites in the Balearic Islands, with several talayots to its north-east."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Capocorb Vell is about 12 kilometres from Llucmajor [S1]; it is on the island of Mallorca [S1]; it is a talayotic site [S1]; it is one of the most highly excavated talayotic sites in the Balearic Islands [S2]; there are several talayots to the north-east of the main site [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Capocorb Vell is a talayotic site (a prehistoric Talayotic-culture settlement) [SUPPORTED: https://en.wikipedia.org/wiki/Capocorb_Vell]; Capocorb Vell lies on the island of Mallorca (Spain) [SUPPORTED: https://en.wikipedia.org/wiki/Capocorb_Vell]; It is about 12 kilometres from Llucmajor [SUPPORTED, no proving quote: https://mallorcasecrets.de/ausfluege/capocorb-vell/]; It is one of the most highly excavated talayotic sites in the Balearic Islands [SUPPORTED: https://de.wikipedia.org/wiki/Capocorb_Vell]; The site has several talayots [SUPPORTED: https://visitllucmajor.com/en/capocorb-vell-un-viaje-a-la-prehistoria-talayotica-de-llucmajor/]; There are several talayots to the north-east of the main site [SUPPORTED: https://en.wikipedia.org/wiki/Capocorb_Vell]"}]'::jsonb),
    ('9c7230d0-e962-4c5f-95c0-3b3ea8cf1b4c'::uuid, 'card_description', NULL, 'Above the Ouse valley lies Offham Hill, a Neolithic causewayed enclosure whose dig yielded about 7,000 worked flints, nearly 300 sherds of pottery, a human burial and animal remains.', 'teaser-card-s009:9c7230d0-e962-4c5f-95c0-3b3ea8cf1b4c:card_description', 'teaser-card-s009 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '202fe24fd2077764eb9a00c76136e9e9e2b33dd99dd8d6fa77ae0c9b4d1c2c20|bbd101c532c6bb3093ea09aeba18426a8355c51b4463f1848f35eb9b3602ca12|bbd101c532c6bb3093ea09aeba18426a8355c51b4463f1848f35eb9b3602ca12', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Above the Ouse valley lies Offham Hill, a Neolithic causewayed enclosure whose dig yielded about 7,000 worked flints, nearly 300 sherds of pottery, a human burial and animal remains."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Offham Hill lies above the Ouse valley [S6]; it is a causewayed enclosure [S1]; the enclosure is Neolithic [S4]; the excavation yielded about 7,000 worked flints [S3]; the excavation yielded nearly 300 sherds of pottery [S3]; the excavation yielded a human burial [S3]; the excavation yielded animal remains [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Offham Hill is a causewayed enclosure (near Lewes, East Sussex, England) [SUPPORTED: https://en.wikipedia.org/wiki/Offham_Hill]; The site lies above the Ouse valley [SUPPORTED: https://en.wikipedia.org/wiki/Offham_Hill]; The enclosure is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Offham_Hill]; The excavation yielded about 7,000 worked flints [SUPPORTED: https://en.wikipedia.org/wiki/Offham_Hill]; The excavation yielded nearly 300 sherds of pottery [SUPPORTED: https://en.wikipedia.org/wiki/Offham_Hill]; The excavation found a human burial [SUPPORTED: https://en.wikipedia.org/wiki/Offham_Hill]; The excavation found animal remains [SUPPORTED: https://en.wikipedia.org/wiki/Offham_Hill]"}]'::jsonb),
    ('9cb2bfc1-76b9-4904-941d-0d3cc7f86d6a'::uuid, 'card_description', 'The original castrum of Rapidum remained until 201 AD, while the town survived until emperor Aurelian when it was destroyed by Berber nomads.', 'Nearly 100 km south of Algiers, a civilian settlement grew up near a Roman fort under Hadrian. Rapidum became a municipium with nearly 4,000 inhabitants under Marcus Aurelius.', 'teaser-card-s009:9cb2bfc1-76b9-4904-941d-0d3cc7f86d6a:card_description', 'teaser-card-s009 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', 'e7743f9b2d7b3b464b229f1d7c6ae5b4a36dce2a667dc0a27df6f895bcb2b2b4|8888c2278af09fe0499781fa056c64e6a027373ffa27926341fdcc4498b70035|8888c2278af09fe0499781fa056c64e6a027373ffa27926341fdcc4498b70035', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Nearly 100 km south of Algiers, a civilian settlement grew up near a Roman fort under Hadrian. Rapidum became a municipium with nearly 4,000 inhabitants under Marcus Aurelius."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Rapidum lies nearly 100 km south of Algiers [S1]; a civilian settlement grew up near a Roman fort [S2]; this happened under Hadrian [S2]; Rapidum was named a municipium [S6]; it had nearly 4,000 inhabitants [S6]; this was under Marcus Aurelius [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Rapidum is a Roman settlement and fort in Mauretania Caesariensis (today Algeria) [SUPPORTED: https://en.wikipedia.org/wiki/Rapidum]; Rapidum lies nearly 100 km south of Algiers [SUPPORTED: https://en.wikipedia.org/wiki/Rapidum]; The Romans built a fort at the site [SUPPORTED: https://en.wikipedia.org/wiki/Rapidum]; A civilian settlement grew up near the Roman fort [SUPPORTED: https://en.wikipedia.org/wiki/Rapidum]; The civilian settlement grew up under Hadrian [SUPPORTED: https://en.wikipedia.org/wiki/Rapidum]; Rapidum became a municipium [SUPPORTED: https://en.wikipedia.org/wiki/Rapidum]; The municipium status and extent date to the reign of Marcus Aurelius [SUPPORTED: https://en.wikipedia.org/wiki/Rapidum]; Rapidum had nearly 4,000 inhabitants under Marcus Aurelius [SUPPORTED: https://en.wikipedia.org/wiki/Rapidum]"}]'::jsonb),
    ('9e34acd6-6cb0-44f1-bf20-97d250838359'::uuid, 'card_description', 'A 142-hectare ancient woodland hiding Bronze Age rock carvings with cup-and-ring marks. The woods were used for charcoal production for millennia.', 'In Sheffield''s Ecclesall Woods, approximately 350 acres once worked for timber and charcoal, a cup and ring-marked stone was found in 1981, dated to the late Neolithic or Bronze Age.', 'teaser-card-s009:9e34acd6-6cb0-44f1-bf20-97d250838359:card_description', 'teaser-card-s009 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'bb62621e51849e1642ee1f35a400c7e8f0dd92abcc7b208ea6ba19a4d60086a7|6ccd56c1e3295b734008cb58d79ab81c1ec8e4e156643f4f0c3ac06c15a5adeb|6ccd56c1e3295b734008cb58d79ab81c1ec8e4e156643f4f0c3ac06c15a5adeb', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In Sheffield''s Ecclesall Woods, approximately 350 acres once worked for timber and charcoal, a cup and ring-marked stone was found in 1981, dated to the late Neolithic or Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Ecclesall Woods is in Sheffield [S1]; the woods cover approximately 350 acres [S2]; the woodland was once used for timber and charcoal [S2]; a cup and ring-marked stone was found (discovered) there in 1981 [S3]; the stone is dated to the late Neolithic or Bronze Age [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Ecclesall Woods is an area of woodland in Sheffield, England (not a built structure) [SUPPORTED: https://en.wikipedia.org/wiki/Ecclesall_Woods]; The woods cover approximately 350 acres [SUPPORTED: https://en.wikipedia.org/wiki/Ecclesall_Woods]; The woodland was once worked for timber and charcoal [SUPPORTED: https://en.wikipedia.org/wiki/Ecclesall_Woods]; A cup and ring-marked stone was found in the woods in 1981 [SUPPORTED: https://en.wikipedia.org/wiki/Ecclesall_Woods]; The cup and ring-marked stone is dated to the late Neolithic or Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Ecclesall_Woods]"}]'::jsonb),
    ('9effdfa3-4808-45e7-be9a-578a870e1899'::uuid, 'card_description', 'Andean burial complex with stone walls and round chullpa towers in the Junin highlands, c. 1200 AD. Chullpas were built above ground so the dead could be revisited - a tradition outlasting the Incas.', 'Its Quechua name means horn village. In Peru''s Junín Region, Waqlamarka holds walls and round burial towers called chullpa, an archaeological site in the Parco District of Jauja Province.', 'teaser-card-s009:9effdfa3-4808-45e7-be9a-578a870e1899:card_description', 'teaser-card-s009 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '7262406b4063ee32147ca89b1c739fb37eb07ecfa58779a099c5d431c627b5d4|b949ff698994d305d74e9b74df1de92e73e340b88a9d4a04c84bdadd0538da6c|b949ff698994d305d74e9b74df1de92e73e340b88a9d4a04c84bdadd0538da6c', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Its Quechua name means horn village. In Peru''s Junín Region, Waqlamarka holds walls and round burial towers called chullpa, an archaeological site in the Parco District of Jauja Province."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the Quechua name Waqlamarka means horn village [S1]; the site is in Peru [S1]; it lies in the Junín Region [S2]; it has walls [S1]; it has round burial towers called chullpa [S1]; it is an archaeological site [S1]; it is in the Parco District [S2]; it is in Jauja Province [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Waqlamarka is an archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Waqlamarka]; Waqlamarka is in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Waqlamarka]; Its Quechua name means horn village [SUPPORTED: https://en.wikipedia.org/wiki/Waqlamarka]; The site has walls [SUPPORTED: https://en.wikipedia.org/wiki/Waqlamarka]; The site has round burial towers [SUPPORTED: https://en.wikipedia.org/wiki/Waqlamarka]; The round burial towers are called chullpa [SUPPORTED: https://en.wikipedia.org/wiki/Waqlamarka]; It lies in Peru''s Junin Region [SUPPORTED: https://en.wikipedia.org/wiki/Waqlamarka]; It lies in Jauja Province [SUPPORTED: https://en.wikipedia.org/wiki/Waqlamarka]; It lies in the Parco District [SUPPORTED: https://en.wikipedia.org/wiki/Waqlamarka]"}]'::jsonb),
    ('9f99919a-d5d6-4384-994b-704ece327ab6'::uuid, 'card_description', 'In 1878 Panagiotis Stamatakis found a beehive tomb that was built in the Mycenaean epoch and that was also reused in later periods.', 'In the territory of Prosymna, a town of ancient Argolis, stood the celebrated temple of Hera. People lived here since the Neolithic, and in 1878 a Mycenaean beehive tomb came to light.', 'teaser-card-s009:9f99919a-d5d6-4384-994b-704ece327ab6:card_description', 'teaser-card-s009 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '35f498475464ba7070047e7ac370f7f7825e16dcd69ac368ab37412a15ca9fdf|20f0f2a5891c52d4e0fd19bb3e00c911bcae54552e483198876e674dc7f158a0|20f0f2a5891c52d4e0fd19bb3e00c911bcae54552e483198876e674dc7f158a0', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "In the territory of Prosymna, a town of ancient Argolis, stood the celebrated temple of Hera. People lived here since the Neolithic, and in 1878 a Mycenaean beehive tomb came to light."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Prosymna is a town of ancient Argolis [S1]; the celebrated temple of Hera (the Heraeum) stood in Prosymna''s territory [S1]; the place has been inhabited since the Neolithic [S2]; a beehive tomb was found in 1878 [S3]; the beehive tomb is Mycenaean [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Prosymna was a town of ancient Argolis [SUPPORTED: https://en.wikipedia.org/wiki/Prosymna]; In the territory of Prosymna stood the celebrated temple of Hera [SUPPORTED: https://en.wikipedia.org/wiki/Prosymna]; People lived at the place since the Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Prosymna]; In 1878 a beehive tomb came to light [SUPPORTED: https://en.wikipedia.org/wiki/Prosymna]; The beehive tomb is Mycenaean [SUPPORTED: https://en.wikipedia.org/wiki/Prosymna]"}]'::jsonb),
    ('a0d4a5ea-fb2c-435c-a8b0-a6e12143b007'::uuid, 'card_description', 'A ruined Neolithic chambered barrow from around 4000 BC, now a jumbled pile of massive sarsen stones. Locals call it the ''Countless Stones'' because legend says you can never count them twice the same.', 'Near Aylesford in Kent lie about 21 stones of Little Kit''s Coty House, also called the Countless Stones: a chambered long barrow constructed circa 4000 BCE, today in a ruined state.', 'teaser-card-s009:a0d4a5ea-fb2c-435c-a8b0-a6e12143b007:card_description', 'teaser-card-s009 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '2c555bcd605d79446c6bf3dce2e4b578ed7dabb76bee955156e3eeeba7aa6fdb|4edaeef5927f97ad2feae826802e26c49080cb47086cfe1e86c281c710db6421|4edaeef5927f97ad2feae826802e26c49080cb47086cfe1e86c281c710db6421', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Near Aylesford in Kent lie about 21 stones of Little Kit''s Coty House, also called the Countless Stones: a chambered long barrow constructed circa 4000 BCE, today in a ruined state."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the monument is near Aylesford [S1]; it is in Kent [S1]; there are about 21 stones at the site [S5]; it is also called the Countless Stones [S1]; it is a chambered long barrow [S1]; it was constructed circa 4000 BCE [S2]; today it survives in a ruined state [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Little Kit''s Coty House is a chambered long barrow [SUPPORTED: https://en.wikipedia.org/wiki/Little_Kit''s_Coty_House]; It lies near Aylesford [SUPPORTED: https://en.wikipedia.org/wiki/Little_Kit''s_Coty_House]; It lies in Kent [SUPPORTED: https://en.wikipedia.org/wiki/Little_Kit''s_Coty_House]; There are about 21 stones at the site [SUPPORTED: https://en.wikipedia.org/wiki/Little_Kit''s_Coty_House]; It is also called the Countless Stones [SUPPORTED: https://en.wikipedia.org/wiki/Little_Kit''s_Coty_House]; It was constructed circa 4000 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Little_Kit''s_Coty_House]; It was constructed (built by people) rather than a natural formation [SUPPORTED: https://en.wikipedia.org/wiki/Little_Kit''s_Coty_House]; Today it survives in a ruined state [SUPPORTED: https://en.wikipedia.org/wiki/Little_Kit''s_Coty_House]"}]'::jsonb),
    ('a0dd99a4-37b3-4b2d-bf8b-0bbaf3c2f53a'::uuid, 'card_description', 'Roman fort at Rochester far north of Hadrian Wall along Dere Street, garrisoned into the 270s AD -- longer than most frontier outposts in hostile northern territory.', 'A long way north of Hadrian''s Wall, along Dere Street, stood Bremenium, a Roman fort built around 80 AD. The First Cohort of Lingones and then of Dalmatians formed its garrison.', 'teaser-card-s009:a0dd99a4-37b3-4b2d-bf8b-0bbaf3c2f53a:card_description', 'teaser-card-s009 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '8b5238acd3130a54eac5e5917189b18d4e60a59ba8a25ed57b9f3fe8e3cfcae9|a8dc1ae776c763aae188e25385ab0e3c3bf165a87075058bee022bc39d90222a|a8dc1ae776c763aae188e25385ab0e3c3bf165a87075058bee022bc39d90222a', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "A long way north of Hadrian''s Wall, along Dere Street, stood Bremenium, a Roman fort built around 80 AD. The First Cohort of Lingones and then of Dalmatians formed its garrison."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the fort lies a long way north of Hadrian''s Wall [S3]; it lay along Dere Street [S2]; Bremenium is a Roman fort [S1]; it was built around 80 AD [S6]; the First Cohort of Lingones and then the First Cohort of Dalmatians formed its garrison [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Bremenium was a Roman fort [SUPPORTED: https://en.wikipedia.org/wiki/Bremenium]; The fort lay a long way north of Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Bremenium]; The fort stood along Dere Street [SUPPORTED: https://en.wikipedia.org/wiki/Bremenium]; Bremenium was built around 80 AD [SUPPORTED: https://en.wikipedia.org/wiki/Bremenium]; The First Cohort of Lingones formed its garrison [SUPPORTED: https://en.wikipedia.org/wiki/Bremenium]; The First Cohort of Dalmatians then formed its garrison [SUPPORTED: https://en.wikipedia.org/wiki/Bremenium]"}]'::jsonb),
    ('a1428be8-db83-4d05-be49-9ee85ed77689'::uuid, 'card_description', 'The Menir da Cabeça do Rochedo is an obelisk-like monument made from limestone, located just north of the town of Lagos.', 'On a hill just outside Portelas, the limestone Menir da Cabeça do Rochedo bears a faint spiral-like engraving. Early Neolithic, it was not funerary, and the end it served is still debated.', 'teaser-card-s009:a1428be8-db83-4d05-be49-9ee85ed77689:card_description', 'teaser-card-s009 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '39f246dc9ebd1b7b0bc000691bf467937f1e9df9545efc505d9488139a294c8c|02282c7f332906f66adee1e1e10ea17ea61e6b787308de67148b0ccdfabb464d|02282c7f332906f66adee1e1e10ea17ea61e6b787308de67148b0ccdfabb464d', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On a hill just outside Portelas, the limestone Menir da Cabeça do Rochedo bears a faint spiral-like engraving. Early Neolithic, it was not funerary, and the end it served is still debated."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the monument is on a hill just outside Portelas [S6]; the menhir is made of limestone [S1]; it bears a faint spiral-like engraving [S2]; it dates to the early Neolithic [S2]; it did not serve funerary purposes [S5]; the end (purpose) it served is still debated [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Menir da Cabeça do Rochedo is a menhir, a standing-stone monument, in Portugal (central claim: what kind of place it is) [SUPPORTED: https://en.wikipedia.org/wiki/Menir_da_Cabe%C3%A7a_do_Rochedo]; The menhir stands on a hill just outside Portelas [SUPPORTED: https://en.wikipedia.org/wiki/Menir_da_Cabe%C3%A7a_do_Rochedo]; The menhir is made of limestone [SUPPORTED: http://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=2233604]; The menhir bears a faint, spiral-like engraving [SUPPORTED: https://en.wikipedia.org/wiki/Menir_da_Cabe%C3%A7a_do_Rochedo]; The menhir dates to the Neolithic period [SUPPORTED: http://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=2233604]; The menhir is specifically Early Neolithic (the state register says only Neolithic and records a Bronze Age settlement nearby; other pages date the menhir to the Bronze Age, so the early date rests on one Wikipedia sentence) [UNVERIFIABLE, no proving quote: None]; The menhir was not funerary [SUPPORTED: https://en.wikipedia.org/wiki/Menir_da_Cabe%C3%A7a_do_Rochedo]; The purpose the menhir served is still debated / unknown [SUPPORTED: https://tomorrowalgarve.com/head-of-the-rock-menir-da-cabeca-do-rochedo/]"}]'::jsonb),
    ('a2b988c2-368a-44ac-a95b-32d73d74a116'::uuid, 'card_description', 'A 50-hectare multivallate fort west of Ightham — the largest Iron Age fort in southeast of the country. Sling stones hint at violence; wooden gates once barred the entrances.', 'West of Ightham in Kent, a bank and ditch enclose about 50 hectares: Oldbury Camp, the largest Iron Age hill fort in south-eastern England, its entrances once barred by wooden gates.', 'teaser-card-s009:a2b988c2-368a-44ac-a95b-32d73d74a116:card_description', 'teaser-card-s009 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'a10cfac449f107cacb4a42925a6780b7997e5321ecb9f00008dad0a47c2be360|fd741f131d8cab777e867bca4d836ffe20b4194c1d8f9c9f7751220f03e9c57b|fd741f131d8cab777e867bca4d836ffe20b4194c1d8f9c9f7751220f03e9c57b', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "West of Ightham in Kent, a bank and ditch enclose about 50 hectares: Oldbury Camp, the largest Iron Age hill fort in south-eastern England, its entrances once barred by wooden gates."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies west of Ightham [S2]; it is in Kent [S2]; a bank and ditch enclose about 50 hectares [S3]; Oldbury Camp is the largest Iron Age hill fort in south-eastern England [S1]; its entrances were barred by wooden gates [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Oldbury Camp is an Iron Age hill fort in Kent near Ightham (central claim: what kind of place it is) [SUPPORTED: https://heritage.kent.gov.uk/Monument/mke247]; The hill fort lies west of Ightham in Kent [SUPPORTED: https://en.wikipedia.org/wiki/Oldbury_Camp]; A bank and ditch (rampart and ditch) form the enclosing defences [SUPPORTED: https://heritage.kent.gov.uk/Monument/mke247]; The enclosure covers about 50 hectares [SUPPORTED: https://heritage.kent.gov.uk/Designation/DKE19047]; Oldbury Camp is the largest Iron Age hill fort in south-eastern England [SUPPORTED: https://en.wikipedia.org/wiki/Oldbury_Camp]; The fort''s entrances were once barred by wooden gates [SUPPORTED: https://en.wikipedia.org/wiki/Oldbury_Camp]"}]'::jsonb),
    ('a2ceca93-fe33-44a6-abe3-de8c41424997'::uuid, 'card_description', 'A fortified Minoan building with 37 rooms opening onto a central court. Its fortification walls are notable because so few Minoan settlements had visible military defenses.', 'On eastern Crete, the fortified Minoan building of Hagia Photia holds 37 rooms that open onto a central court, yet do not necessarily connect to the rooms beside them.', 'teaser-card-s009:a2ceca93-fe33-44a6-abe3-de8c41424997:card_description', 'teaser-card-s009 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', '788bdff68d927c6016943392f366203767b6215d9f351097c0f53a4368fd6bb7|4217b452648e4de468b2f2e946a5c81bd2fb3ea7ddf168864d07ac95487fa66f|4217b452648e4de468b2f2e946a5c81bd2fb3ea7ddf168864d07ac95487fa66f', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On eastern Crete, the fortified Minoan building of Hagia Photia holds 37 rooms that open onto a central court, yet do not necessarily connect to the rooms beside them."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is on eastern Crete [S1]; it is a fortified Minoan building [S1]; the building has 37 rooms [S2]; the rooms open onto a central court [S2]; the rooms do not necessarily connect to adjoining rooms [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Hagia Photia is an archaeological site of a fortified Minoan building on eastern Crete (central claim: what kind of place it is, and where) [SUPPORTED: https://en.wikipedia.org/wiki/Hagia_Photia]; The Minoan building was fortified (surrounded by a fortification wall) [SUPPORTED: http://www.minoancrete.com/agphotia.htm]; The site lies in eastern Crete, about five kilometres east of Siteia (Sitia) [SUPPORTED: http://www.minoancrete.com/agphotia.htm]; The building has 37 rooms [SUPPORTED: http://www.minoancrete.com/agphotia.htm]; The rooms open onto a central court [SUPPORTED: http://www.minoancrete.com/agphotia.htm]; The rooms do not necessarily connect to the rooms beside them [SUPPORTED: https://en.wikipedia.org/wiki/Hagia_Photia]"}]'::jsonb),
    ('a2df5acf-6b70-48e1-a8e6-869e1d0dffbc'::uuid, 'card_description', 'Punic-Roman tower in San Gwann with origins that may reach into prehistory. The site later served as a Muslim cemetery, then a church—three faiths layered onto a single structure.', 'Of Ta'' Ċieda Tower, a Punic-Roman tower in San Ġwann, a dilapidated base remains. In the Muslim period, the area at the tower was used at least as an Islamic cemetery.', 'teaser-card-s009:a2df5acf-6b70-48e1-a8e6-869e1d0dffbc:card_description', 'teaser-card-s009 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', 'ee3bcef915670a236e420add557d015b63c23c7cd158fbbb17dfc684d049d751|c98628f44b8a34c4124ff730efd4f2f78df4832c840363f3d609a3d75206d6ce|c98628f44b8a34c4124ff730efd4f2f78df4832c840363f3d609a3d75206d6ce', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Of Ta'' Ċieda Tower, a Punic-Roman tower in San Ġwann, a dilapidated base remains. In the Muslim period, the area at the tower was used at least as an Islamic cemetery."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Ta'' Ċieda Tower is a Punic-Roman tower [S1]; it is in San Ġwann [S1]; a dilapidated base remains [S4]; in the Muslim period the area at the tower was used at least as an Islamic cemetery [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Ta'' Ċieda Tower is a Punic-Roman tower (central claim: what kind of place it is) [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_%C4%8Aieda_Tower]; The tower stands in San Ġwann, Malta [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_%C4%8Aieda_Tower]; Only a dilapidated base of the tower remains [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_%C4%8Aieda_Tower]; In the Muslim period the area at the tower was used at least as an Islamic cemetery [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_%C4%8Aieda_Tower]"}]'::jsonb),
    ('a36bb548-bebc-4606-af26-9cded2b3cded'::uuid, 'card_description', '5th-millennium BC earthwork complex near Vatin - four concentric earthen circles ~150 m in diameter. Thought to be astronomical observatories, predating Stonehenge''s first phase by over a millennium.', 'Near the village of Vatin, four regular concentric circles form a slight elevation: the Vatin Circles, around 150 meters across. How they were created, or why, is not known for sure.', 'teaser-card-s009:a36bb548-bebc-4606-af26-9cded2b3cded:card_description', 'teaser-card-s009 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'cee9c4e6ecc04e7123b982d686dcb9985eb920cf3568469072297ab1b2491376|dbb893bc97baef602de1807c17e1b7ef0feffc2dff8244ee83f162b2cdb5547e|dbb893bc97baef602de1807c17e1b7ef0feffc2dff8244ee83f162b2cdb5547e', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Near the village of Vatin, four regular concentric circles form a slight elevation: the Vatin Circles, around 150 meters across. How they were created, or why, is not known for sure."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site is near the village of Vatin [S1]; it consists of four regular concentric circles [S2]; the circles form a slight elevation [S2]; the Vatin Circles are around 150 meters across [S3]; it is not known for sure how the circles were created or what their purpose was [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Vatin Circles are an archaeological site of concentric circles (central claim: what kind of place it is) [SUPPORTED: https://en.wikipedia.org/wiki/Vatin_circles]; The site lies near the village of Vatin [SUPPORTED: https://vojvodinauzivo.rs/vatinski-krugovi-kalendar-drevnih-vincanaca/]; The site consists of four regular concentric circles [SUPPORTED: https://en.wikipedia.org/wiki/Vatin_circles]; The four circles together form a slight elevation [SUPPORTED: https://sr.wikipedia.org/wiki/%D0%92%D0%B0%D1%82%D0%B8%D0%BD%D1%81%D0%BA%D0%B8_%D0%BA%D1%80%D1%83%D0%B3%D0%BE%D0%B2%D0%B8]; The circles are around 150 meters across [SUPPORTED: https://vojvodinauzivo.rs/vatinski-krugovi-kalendar-drevnih-vincanaca/]; How the circles were created is not known for sure [SUPPORTED: https://en.wikipedia.org/wiki/Vatin_circles]; Why the circles were made (their function) is not known [SUPPORTED: https://www.pancevac-online.rs/en/417692/mysterious-circles-near-vrsac-is-serbia-hiding-a-forgotten-civilization/]"}]'::jsonb),
    ('a45b9287-fe45-43b0-a8d6-8c434e16e65b'::uuid, 'card_description', 'Remains date mostly from the Hellenistic period and include the acropolis, a temple of Apollo and an agora.', 'Often called the Pearl of the Black Sea, Nesebar is a small city in two parts, its ancient part on a peninsula. Its remains include an acropolis, a temple of Apollo and an agora.', 'teaser-card-s009:a45b9287-fe45-43b0-a8d6-8c434e16e65b:card_description', 'teaser-card-s009 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '03acbdd880df7426c43b91afa3998d08e6322812b9f5947ec2f4fccd679488b9|6a8ae297451fcb7e92ca5f893d16411fd45cfc6bb1351a7eb03993f615c60702|6a8ae297451fcb7e92ca5f893d16411fd45cfc6bb1351a7eb03993f615c60702', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Often called the Pearl of the Black Sea, Nesebar is a small city in two parts, its ancient part on a peninsula. Its remains include an acropolis, a temple of Apollo and an agora."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Nesebar is often called the Pearl of the Black Sea [S1]; it is a small city [S2]; the city is in two parts [S2]; its ancient part is on a peninsula [S2]; its remains include an acropolis [S5]; its remains include a temple of Apollo [S5]; its remains include an agora [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Nesebar is a city (an ancient city and seaside resort) [SUPPORTED: https://en.wikipedia.org/wiki/Nesebar]; Nesebar is in Bulgaria [SUPPORTED: https://en.wikipedia.org/wiki/Nesebar]; Nesebar is often called the Pearl of the Black Sea [SUPPORTED: https://en.wikipedia.org/wiki/Nesebar]; Nesebar is a small city [SUPPORTED: https://en.wikipedia.org/wiki/Nesebar]; Nesebar is a city in two parts [SUPPORTED: https://en.wikipedia.org/wiki/Nesebar]; The ancient part of Nesebar lies on a peninsula [SUPPORTED: https://en.wikipedia.org/wiki/Nesebar]; Nesebar''s remains include an acropolis [SUPPORTED: https://en.wikipedia.org/wiki/Nesebar]; Nesebar''s remains include a temple of Apollo [SUPPORTED: https://en.wikipedia.org/wiki/Nesebar]; Nesebar''s remains include an agora [SUPPORTED: https://en.wikipedia.org/wiki/Nesebar]"}]'::jsonb),
    ('a52e274f-3e08-44b5-a03f-1d564fede9a2'::uuid, 'card_description', 'The monumental main gate of Classical Athens, built in 478 BC. The Great Panathenaea procession — the city''s most important festival — began here.', 'The Dipylon, the Two-Gated, was the main gate of Classical Athens, where the procession of the Great Panathenaea began. Erected in 478 BC, it was rebuilt in the 300s BC.', 'teaser-card-s009:a52e274f-3e08-44b5-a03f-1d564fede9a2:card_description', 'teaser-card-s009 (teaser-card): teaser card, 169 characters, checked PASS, web-verified VERIFIED', 'a97516bee8ea5c44db9091bf46ba04284830058c3b78ba8c22d91e32b1bac6e7|b2f7c45ee0c2626d962cb066a12ebd699e16be0126616279a82d541e05592991|b2f7c45ee0c2626d962cb066a12ebd699e16be0126616279a82d541e05592991', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Dipylon, the Two-Gated, was the main gate of Classical Athens, where the procession of the Great Panathenaea began. Erected in 478 BC, it was rebuilt in the 300s BC."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Dipylon means Two-Gated [S1]; it was the main gate of Classical Athens [S1]; the procession of the Great Panathenaea began there [S3]; it was erected in 478 BC [S4]; it was rebuilt in the 300s BC [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Dipylon was the main gate of Classical Athens [SUPPORTED: https://en.wikipedia.org/wiki/Dipylon]; Dipylon means the Two-Gated [SUPPORTED: https://en.wikipedia.org/wiki/Dipylon]; The procession of the Great Panathenaea began at the Dipylon [SUPPORTED: https://en.wikipedia.org/wiki/Dipylon]; The Dipylon was erected in 478 BC [SUPPORTED: https://en.wikipedia.org/wiki/Dipylon]; The Dipylon was rebuilt in the 300s BC [SUPPORTED: https://en.wikipedia.org/wiki/Dipylon]"}]'::jsonb),
    ('a55ddaef-8835-4749-ab18-978c295cf1b5'::uuid, 'card_description', 'The theatre was built in the second half of the 1st century BC, on the southwestern slopes of the Pefkakia hill.', 'On the southwestern slopes of the Pefkakia hill, the Second Ancient Theatre was left unfinished: thirteen tiers of grey-white marble seats, and for the rest probably seats of wood.', 'teaser-card-s009:a55ddaef-8835-4749-ab18-978c295cf1b5:card_description', 'teaser-card-s009 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'f91799db6466f8b7653fe37cfed9d032f38e2c17b110679c27fa90c7dcbc81b8|d5afccff96719fa8549038106924c23ca969e0cf39d6a2d29b3f99719263eb61|d5afccff96719fa8549038106924c23ca969e0cf39d6a2d29b3f99719263eb61', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "On the southwestern slopes of the Pefkakia hill, the Second Ancient Theatre was left unfinished: thirteen tiers of grey-white marble seats, and for the rest probably seats of wood."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the theatre is on the southwestern slopes of the Pefkakia hill [S2]; the theatre was left unfinished [S5, S6]; the seating has thirteen tiers [S6]; the tiers have seats of grey-white marble [S6]; for the rest of the seating, wooden seats were probably used [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "The Second Ancient Theatre is an ancient Greek theatre in Larissa, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Second_Ancient_Theatre,_Larissa]; The theatre lies on the southwestern slopes of the Pefkakia hill [SUPPORTED: https://en.wikipedia.org/wiki/Second_Ancient_Theatre,_Larissa]; The Second Ancient Theatre was left unfinished [SUPPORTED: https://en.wikipedia.org/wiki/Second_Ancient_Theatre,_Larissa]; The seating has thirteen tiers of grey-white marble seats [SUPPORTED: https://en.wikipedia.org/wiki/Second_Ancient_Theatre,_Larissa]; The rest of the seating was probably of wood [SUPPORTED: https://en.wikipedia.org/wiki/Second_Ancient_Theatre,_Larissa]"}]'::jsonb),
    ('a56bd06f-2305-409d-99e5-47e4f7e29ae4'::uuid, 'card_description', 'The Chachapoya built cliff-face tombs resembling miniature houses at 2,800 m altitude. Funerary buildings cling to the limestone rock like birdhouses.', 'At 2,800 m above sea level in Peru''s Santo Tomás District stand the funeral buildings of Revash, where a collapsed mausoleum roof covered and protected the cultural remains.', 'teaser-card-s009:a56bd06f-2305-409d-99e5-47e4f7e29ae4:card_description', 'teaser-card-s009 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', 'bf3411dba8cdd86e4dcec4cf497fcffbc8d3635f59639eba0241c6514a91aa21|181c6d2b111363cbdb94613812d0ed340212330dd55ab70d0d2c890f68275b65|181c6d2b111363cbdb94613812d0ed340212330dd55ab70d0d2c890f68275b65', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "At 2,800 m above sea level in Peru''s Santo Tomás District stand the funeral buildings of Revash, where a collapsed mausoleum roof covered and protected the cultural remains."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the funeral buildings are at 2,800 m above sea level [S2]; they are in Peru''s Santo Tomás District [S1]; Revash has funeral buildings (a funerary complex) [S1, S2]; the roof of a mausoleum collapsed [S3]; the collapsed roof covered and protected the cultural remains [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Revash is a funerary complex of funeral buildings [SUPPORTED: https://en.wikipedia.org/wiki/Revash]; Revash is in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Revash]; Revash is in the Santo Tomás District [SUPPORTED: https://en.wikipedia.org/wiki/Revash]; The funeral buildings of Revash are at 2,800 m above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Revash]; The roof of a mausoleum at Revash collapsed [SUPPORTED: https://en.wikipedia.org/wiki/Revash]; The collapsed mausoleum roof covered and protected the cultural remains [SUPPORTED: https://en.wikipedia.org/wiki/Revash]"}]'::jsonb),
    ('a621b66e-1fda-41b4-9c34-d1a3e7486bd5'::uuid, 'card_description', 'A 20-hectare fortress that served as a stronghold of the ancient kingdom of Colchis. Multiple layers of ruins span from the 4th century BC through the 6th century AD.', 'By the Tekhuri River lie the ruins of Nokalakevi, the Archaeopolis of Byzantine historians. In the war of AD 540-562 the Persians'' failure to take it cost them control of Lazika.', 'teaser-card-s009:a621b66e-1fda-41b4-9c34-d1a3e7486bd5:card_description', 'teaser-card-s009 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', 'c694fef9d2c58566667656248aebd6d3a659d236bfc57a210a6abe7385501631|9a8bd5bd392dd2a0a39dde040ca082384cfd68d030c15e15aa8d9fe604405853|9a8bd5bd392dd2a0a39dde040ca082384cfd68d030c15e15aa8d9fe604405853', '[{"source": "lane WB run wb-ws-2026-09-27-04: writer teaser-wb-ws-2026-09-27-04-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "By the Tekhuri River lie the ruins of Nokalakevi, the Archaeopolis of Byzantine historians. In the war of AD 540-562 the Persians'' failure to take it cost them control of Lazika."}, {"source": "lane WB run wb-ws-2026-09-27-04: checker teaser-wb-ws-2026-09-27-04-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "the site lies by the Tekhuri River [S1]; Nokalakevi is a ruin [S1]; Byzantine historians knew the site as Archaeopolis [S2]; in the war of AD 540-562 the Persians failed to take it [S5]; that failure cost the Persians control of Lazika [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-04: verifier teaser-wb-ws-2026-09-27-04-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-04/OUTCOMES.jsonl", "quote": "Nokalakevi is a ruined site (ruins of a fortress) in Georgia [SUPPORTED: https://en.wikipedia.org/wiki/Nokalakevi]; The ruins of Nokalakevi lie by the Tekhuri River [SUPPORTED: https://en.wikipedia.org/wiki/Nokalakevi]; Nokalakevi is the Archaeopolis of Byzantine historians [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Nokalakevi]; The war between Byzantines and Persians took place in AD 540-562 [SUPPORTED: https://en.wikipedia.org/wiki/Nokalakevi]; The Persians failed to take Nokalakevi in that war [SUPPORTED: https://en.wikipedia.org/wiki/Nokalakevi]; The Persians'' failure to take Nokalakevi cost them control of Lazika [SUPPORTED: https://en.wikipedia.org/wiki/Nokalakevi]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s009', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s009'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s009'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK: nothing may have changed
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s009'
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
-- `_teaser_card_plan` is a CREATE TEMP TABLE, so it lives in this session's `pg_temp_N` schema and
-- `nspname = 'public'` could never match it - the old form of this read was 0 whatever happened.
-- `to_regclass('pg_temp....')` resolves the current session's temp schema and is NULL when the
-- table is gone, so this reads 1 exactly when a leftover exists.
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
